window.HHA=[{"ch":1,"cfr":"(b)(3)(i)","observed":true,"title":["Wòl ou, limit travay ou ak kominikasyon","Your role, scope and communication"],"src":["S6","S12"],"sections":[{"h":["Wòl ou nan ekip la","Your role on the team"],"src":["S12"],"b":[["p","Yon enfimyè (RN) oswa yon terapis asiyen w bay yon kliyan, epi li ekri enstriksyon swen pou ou. Ou fè pati ekip entèdisiplinè a: enfimyè, terapis, travayè sosyal ak ou menm.","A registered nurse (RN) or a therapist assigns you to a client and writes care instructions for you. You are part of the interdisciplinary team: nurses, therapists, social workers and you."],["li","Ou rapòte chanjman nan kondisyon kliyan an bay enfimyè a oswa terapis la.","You report changes in the client's condition to the nurse or therapist."],["li","Ou ranpli dosye yo dapre règ ajans ou.","You complete records according to your agency's policies."],["li","Ou ka patisipe nan reyinyon ekip la an pèsòn, pa telefòn oswa pa videyo. Sa w obsève enpòtan, paske ou pase plis tan ak kliyan an.","You may join team meetings in person, by phone or by video. What you observe matters, because you spend more time with the client."]]},{"h":["Sa w gen dwa fè","What you may do"],"src":["S12"],"b":[["p","Yon ed swen a domisil fè sèlman travay ki:","A home health aide only does tasks that are:"],["n","Doktè a oswa yon pratisyen otorize mande.","Ordered by the doctor or an allowed practitioner."],["n","Ekri nan plan swen an.","Written in the plan of care."],["n","Lwa leta a pèmèt.","Allowed under state law."],["n","Ou te resevwa fòmasyon pou yo.","Covered by your training."],["p","Travay ou gen ladan: swen pèsonèl dirèk, ti pwosedi senp pou ede enfimyè a oswa terapis la, ede kliyan an mache oswa fè egzèsis, epi ede l ak medikaman li konn pran pou kont li.","Your duties include: hands-on personal care, simple procedures that extend nursing or therapy, help with walking or exercises, and help with medications the client normally takes on their own."]]},{"h":["Ede ak medikaman: yon wòl pasif sèlman","Helping with medications: a passive role only"],"src":["S12"],"b":[["p","Règ federal la di ed la ka gen sèlman yon wòl pasif. Egzanp sa w ka fè:","Federal guidance says the aide may take only a passive role. Examples of what you may do:"],["li","Pote medikaman an bay kliyan an, nan bwat grenn li oswa nan veso li, si l mande w.","Bring the medication to the client, in their pill organizer or container, when they ask."],["li","Ba l dlo oswa yon lòt likid pou l pran l.","Give fluids to take it with."],["li","Fè l sonje lè pou l pran medikaman li.","Remind the client to take a medication."],["li","Mete yon krèm san preskripsyon sou po ki pa blese, jan yo te montre w.","Apply a non-prescription cream to unbroken skin, as you were instructed."],["p","Pa janm chwazi, chanje oswa bay yon dòz, ni bay piki. Si w pa sèten, rele enfimyè a.","Never choose, change or give a dose, and never give injections. If you are not sure, call the nurse."]]},{"h":["Pale ak kliyan an ak fanmi an","Talking with the client and family"],"src":["S12"],"b":[["p","Gid federal la di yon bon ed kenbe yon kominikasyon ouvè: li eksplike sa l pral fè, li poze kesyon ouvè, li mande opinyon kliyan an, epi li reponn a bezwen kliyan an, reprezantan l, moun k ap okipe l ak fanmi l.","Federal guidance says a good aide keeps open communication: they explain what they will do, ask open-ended questions, ask for the client's feedback, and respond to the needs of the client, their representative, caregivers and family."],["li","Frape anvan w antre, prezante w, epi rele kliyan an jan l pito.","Knock before entering, introduce yourself, and call the client by the name they prefer."],["li","Kesyon ouvè: «Kijan w te dòmi yè swa?» olye «Ou te dòmi?»","Open-ended question: “How did you sleep last night?” instead of “Did you sleep?”"],["li","Pale klè epi anfas moun ki gen pwoblèm tande. Di moun ki pa wè byen kote bagay yo ye.","Speak clearly and face people with hearing loss. Tell people with low vision where things are."],["li","Si kliyan an pa pale lang ou byen, mande ajans ou pou sèvis entèprèt. Ajans yo dwe bay enfòmasyon nan yon lang kliyan an konprann.","If the client does not speak your language well, ask your agency for interpreter services. Agencies must give information in a language the client understands."]]},{"h":["Pale ak ekip la","Talking with the team"],"src":["S6"],"b":[["li","Li enstriksyon swen yo anvan chak vizit. Si yon bagay pa klè, mande anvan w kòmanse.","Read the care instructions before each visit. If something is unclear, ask before you start."],["li","Lè w rapòte, di kisa ou wè, ki lè, ak konbyen. Egzanp: «Tanperati 100.8°F a 10è, li di l gen frison.»","When you report, say what you saw, when, and how much. Example: “Temperature 100.8°F at 10 a.m.; she says she has chills.”"],["li","Sou egzamen konpetans lan, yon enfimyè ap gade w pandan w ap kominike ak yon kliyan oswa yon moun k ap jwe wòl kliyan.","On the competency evaluation, a nurse watches you communicate with a client or a person playing the client."]]}],"terms":[["plan of care","plan swen"],["care instructions","enstriksyon swen"],["interdisciplinary team","ekip entèdisiplinè"],["registered nurse (RN)","enfimyè (RN)"],["self-administered medication","medikaman kliyan an pran pou kont li"],["open-ended question","kesyon ouvè"],["interpreter","entèprèt"]],"qs":[["h101",1,["registered nurse (RN)","enfimyè (RN)"],["Kiyès ki asiyen w bay yon kliyan epi ki ekri enstriksyon swen ou?","Fanmi kliyan an","Yon enfimyè (RN) oswa yon terapis","Lòt ed swen yo","Ou menm, apre premye vizit la","Yon RN oswa yon lòt pwofesyonèl kalifye (terapis) asiyen ed la bay yon kliyan espesifik epi ekri enstriksyon swen yo."],["Who assigns you to a client and writes your care instructions?","The client's family","A registered nurse or a therapist","Other aides","You, after the first visit","An RN or another qualified professional (a therapist) assigns the aide to a specific client and writes the care instructions."]],["h102",2,["self-administered medication","medikaman kliyan an pran pou kont li"],["Ki èd ak medikaman yon ed swen a domisil gen dwa bay?","Chwazi dòz la si kliyan an gen doulè","Bay yon piki ensilin","Fè kliyan an sonje lè pou l pran medikaman li","Kraze grenn yo pou mete nan manje san enfimyè a pa di l","Ed la ka gen yon wòl pasif sèlman: fè kliyan an sonje, pote medikaman an, ba l dlo, oswa mete yon krèm san preskripsyon sou po ki pa blese."],["Which help with medications is a home health aide allowed to give?","Choose the dose if the client is in pain","Give an insulin injection","Remind the client when to take their medication","Crush pills into food without the nurse's direction","The aide may take only a passive role: reminding, bringing the medication, giving fluids, or applying a non-prescription cream to unbroken skin."]],["h103",0,["scope","limit travay"],["Kliyan an mande w chanje pansman sou blesi li, men sa pa nan plan swen an. Kisa ou fè?","Pa fè l; rele enfimyè a oswa sipèvizè a anvan","Fè l paske l mande w","Mande vwazen an ede w","Fè l epi pa ekri l","Ou fè sèlman travay ki nan plan swen an epi ou te resevwa fòmasyon pou yo. Tcheke ak enfimyè a."],["The client asks you to change a wound dressing, but it is not in the plan of care. What do you do?","Do not do it; call the nurse or supervisor first","Do it because the client asked","Ask a neighbor to help","Do it and leave it out of your notes","You only do tasks that are in the plan of care and covered by your training. Check with the nurse."]],["h104",3,["open communication","kominikasyon ouvè"],["Dapre gid federal la, kisa «kominikasyon ouvè» vle di pou yon ed?","Pale sèlman ak enfimyè a sou swen kliyan an, janm ak fanmi an","Fè travay la san pale pou pa deranje kliyan an","Ba kliyan an ak fanmi an tout enfòmasyon medikal ki nan dosye a ou menm","Eksplike sa w pral fè, poze kesyon ouvè, epi reponn a bezwen kliyan an ak fanmi l","Kominikasyon ouvè vle di eksplike, poze kesyon ouvè, mande opinyon, epi reponn a bezwen kliyan an, reprezantan l ak fanmi l."],["According to federal guidance, what does “open communication” mean for an aide?","Talking only with the nurse about the client's care, never with the family","Working silently so you do not bother the client","Giving the client and family all the medical information in the chart yourself","Explaining what you will do, asking open-ended questions, and responding to the client's and family's needs","Open communication means explaining, asking open-ended questions, seeking feedback, and responding to the needs of the client, representative and family."]],["h105",1,["open-ended question","kesyon ouvè"],["Ki kesyon sa yo ki se yon kesyon ouvè?","Ou te manje?","Kijan ou santi w jodi a?","Ou gen doulè, wi oswa non?","Ou pare?","Yon kesyon ouvè pa ka reponn ak wi oswa non. Li ba w plis enfòmasyon sou kijan kliyan an ye."],["Which of these is an open-ended question?","Did you eat?","How are you feeling today?","Are you in pain, yes or no?","Are you ready?","An open-ended question cannot be answered with yes or no. It tells you more about how the client is doing."]],["h106",2,["interpreter","entèprèt"],["Kliyan w lan pa pale Anglè byen epi ou pa pale lang li. Kisa ki pi bon?","Pale pi fò e pi dousman an Anglè","Fè siy ak men sèlman, san esplikasyon","Mande ajans ou pou sèvis entèprèt","Pa pale ak li ditou","Ajans yo dwe bay enfòmasyon nan yon lang kliyan an konprann. Mande sèvis entèprèt."],["Your client does not speak English well and you do not speak their language. What is best?","Speak louder and more slowly in English","Use gestures only and skip the explanations","Ask your agency for interpreter services","Avoid talking to them","Agencies must give information in a language the client understands. Ask for interpreter services."]],["hha1",0,["care plan","plan swen"],["Kisa ki di yon ed swen a domisil ki travay pou l fè pou yon kliyan?","Plan swen enfimyè oswa sipèvizè a ekri","Sa fanmi an mande jou sa a","Sa ed la panse ki pi bon","Vwazen kliyan an","Swiv plan swen ki ekri a. Si yon moun mande w yon travay ki pa ladan l, verifye ak sipèvizè w anvan."],["What tells a home health aide which tasks to do for a client?","The care plan from the nurse or supervisor","Whatever the family asks for that day","What the aide thinks is best","The client's neighbors","Follow the written care plan. If someone asks for a task that is not on it, check with your supervisor first."]],["hha7",1,["dose","dòz"],["Kliyan w lan mande w ba l plis grenn pou doulè l. Kisa ou fè?","Ba l pi gwo dòz la si l di l gen doulè","Pa chanje dòz la; rapòte sa bay enfimyè a","Ba l mwatye sa l mande a anplis","Mande yon moun nan fanmi an pou l deside dòz la","Pa janm chanje yon medikaman oswa yon dòz. Rapòte doulè a ak demann lan bay enfimyè oswa sipèvizè a."],["Your client asks you for a bigger dose of their pain pill. What do you do?","Give the bigger dose if they say they are in pain","Do not change the dose; report it to the nurse","Give half of the extra amount","Ask a family member to decide on the dose","Never change a medication or dose. Report the pain and the request to the nurse or supervisor."]],["h107",3,["injection","piki"],["Kliyan w lan mande w ba l piki ensilin li paske men l ap tranble. Kisa ou fè?","Ba l li, paske kliyan an mande w","Ba l li si yon moun nan fanmi an ap gade","Ba l mwatye dòz la pou pi an sekirite","Pa ba l li; rele enfimyè a","Ed swen pa janm bay piki ni dòz. Wòl ou ak medikaman se yon wòl pasif sèlman. Rele enfimyè a."],["Your client asks you to give their insulin shot because their hands are shaking. What do you do?","Give it, since the client asked","Give it if a family member watches","Give half the dose to be safe","Do not give it; call the nurse","Aides never give injections or doses. Your role with medications is passive only. Call the nurse."]],["h108",1,["introduce yourself","prezante w"],["Ou rive pou premye vizit ak yon nouvo kliyan. Kisa pou w fè an premye?","Kòmanse swen an touswit pou w gen tan fè tout travay yo","Frape, prezante w, epi mande l ki jan li pito yo rele l","Rele l pa ti non l touswit pou w sanble zanmi","Mande fanmi an eksplike kiyès ou ye","Frape anvan w antre, prezante w, epi rele kliyan an jan l pito. Sa montre respè epi li bati konfyans."],["You arrive for a first visit with a new client. What should you do first?","Start care right away so you have time for every task","Knock, introduce yourself, and ask what name they prefer","Use their first name right away to sound friendly","Ask the family to explain who you are","Knock before entering, introduce yourself, and call the client by the name they prefer. This shows respect and builds trust."]],["h109",2,["hearing loss","pwoblèm tande"],["Kliyan w lan gen pwoblèm tande. Kijan pou w pale avè l?","Rele fò pou l tande w","Pale depi lòt chanm nan","Kanpe anfas li epi pale klè","Pale sèlman ak fanmi an","Kanpe anfas moun nan pou l wè figi w, epi pale klè. Lè w rele, mo yo vin pi difisil pou konprann."],["Your client has hearing loss. How should you speak with them?","Shout so they can hear you","Speak from the next room","Face them and speak clearly","Talk only to the family","Face the person so they can see your face, and speak clearly. Shouting makes words harder to understand."]],["h110",0,["low vision","pa wè byen"],["Kliyan w lan pa wè byen. Ou mete plato manje midi a devan l. Kisa ki ede plis?","Di l kote chak manje ak bwason ye sou plato a","Ba l manje nan bouch pou l pa jete","Deplase afè l yo pou chanm nan rete pwòp","Pa di anyen pou l pa wont","Di moun ki pa wè byen kote bagay yo ye. Konsa li ka manje poukont li, san danje."],["Your client has low vision. You set their lunch tray in front of them. What helps most?","Tell them where each food and drink is on the tray","Feed them so they do not spill","Move their things around to keep the room neat","Say nothing so they are not embarrassed","Tell a person with low vision where things are. Then they can eat on their own, safely."]],["h111",2,["care instructions","enstriksyon swen"],["Anvan yon vizit, ou li enstriksyon swen yo epi yon travay pa klè pou ou. Kisa ou fè?","Sote travay sa a jodi a","Fè l jan w te fè l pou yon lòt kliyan","Mande enfimyè a oswa sipèvizè w anvan w kòmanse","Mande kliyan an kijan pou w fè l","Li enstriksyon swen yo anvan chak vizit. Si yon bagay pa klè, mande anvan w kòmanse, pa apre."],["Before a visit, you read the care instructions and one task is not clear to you. What do you do?","Skip that task today","Do it the way you did for another client","Ask the nurse or supervisor before you start","Ask the client how to do it","Read the care instructions before each visit. If something is unclear, ask before you start, not after."]]],"check":["h101","h102","h103","h104","h105"]},{"ch":2,"cfr":"(b)(3)(ii)","title":["Obsève, rapòte ak ekri","Observing, reporting and documenting"],"src":["S6","S12","S1"],"sections":[{"h":["Obsève ak sans ou","Observe with your senses"],"src":["S1"],"b":[["p","Ou se je ak zòrèy ekip la lakay kliyan an. Sèvi ak tout sans ou: sa w wè, sa w tande, sa w santi (sant), ak sa w touche.","You are the team's eyes and ears in the client's home. Use all your senses: what you see, hear, smell and touch."],["li","Konnen sa ki nòmal pou kliyan sa a. Li plan swen an ak nòt vizit anvan yo.","Know what is normal for this client. Read the care plan and earlier visit notes."],["li","Obsèvasyon objektif: sa w ka wè oswa mezire. Egzanp: «Cheviy goch anfle.»","Objective observation: what you can see or measure. Example: “Left ankle is swollen.”"],["li","Obsèvasyon subjektif: sa kliyan an di w li santi. Ekri l ak pwòp mo l, ant gimè. Egzanp: kliyan an di: «Tèt mwen vire.»","Subjective observation: what the client tells you they feel. Write it in their own words, in quotes. Example: client says, “I feel dizzy.”"]]},{"h":["Kilè pou w rapòte","When to report"],"src":["S12","S6"],"b":[["p","Ed swen yo oblije rapòte chanjman nan kondisyon kliyan an bay enfimyè a oswa terapis la.","Aides must report changes in the client's condition to the nurse or therapist."],["li","Touswit: doulè nan pwatrin, souf kout, yon tonbe, konfizyon toudenkou, san k ap koule, siy abi, oswa nenpòt bagay ki fè w pè pou sekirite kliyan an. Rele 911 pou yon ijans ki menase lavi.","Right away: chest pain, shortness of breath, a fall, sudden confusion, bleeding, signs of abuse, or anything that makes you worried about the client's safety. Call 911 for a life-threatening emergency."],["li","Nan fen vizit la oswa dapre règ ajans ou: ti chanjman tankou mwens apeti, yon ti wouj sou po a, oswa dòmi mal.","At the end of the visit or by agency policy: smaller changes such as less appetite, a small red area on the skin, or poor sleep."],["li","Lè w ap rapòte, bay fè yo: kisa, ki lè, konbyen, ak sa kliyan an di.","When you report, give the facts: what, when, how much, and what the client said."]]},{"h":["Ekri nòt ou","Writing your notes"],"src":["S12","S1"],"b":[["li","Ekri sa w fè apre w fin fè l, pa janm anvan.","Document care after you give it, never before."],["li","Ekri fè, chif ak lè, pa opinyon. «Manje 50% manje midi» pi bon pase «li pa t grangou».","Write facts, numbers and times, not opinions. “Ate 50% of lunch” is better than “she wasn't hungry.”"],["li","Ekri sèlman sa ou menm ou fè oswa ou wè.","Write only what you yourself did or saw."],["li","Si w fè yon erè, swiv règ ajans ou pou korije l. Pa janm efase oswa itilize likid blan.","If you make a mistake, follow your agency's policy to correct it. Never erase or use correction fluid."],["li","Dosye a se yon dokiman legal. Ranpli l dapre règ ajans lan chak fwa.","The record is a legal document. Complete it according to agency policy every time."]]},{"h":["Konfidansyalite","Confidentiality"],"src":["S1","S27"],"b":[["p","Enfòmasyon sante kliyan an prive. Pataje l sèlman ak ekip swen ki bezwen l. Pa pale sou kliyan yo ak zanmi, vwazen oswa sou rezo sosyal.","The client's health information is private. Share it only with the care team members who need it. Do not talk about clients with friends, neighbors or on social media."],["li","Pa pran ni poste foto lakay kliyan an san règ ajans ou pèmèt li. Menm yon foto bèt oswa yon chanm ka montre ki moun kliyan an ye, kote l rete, oswa ekipman medikal li.","Do not take or post photos in a client's home unless your agency's policy allows it. Even a photo of a pet or a room can reveal who the client is, where they live, or their medical equipment."]]}],"terms":[["objective","objektif"],["subjective","subjektif"],["report","rapòte"],["document","ekri nan dosye"],["clinical record","dosye klinik"],["confidential","konfidansyèl"]],"qs":[["h201",0,["objective observation","obsèvasyon objektif"],["Kiyès nan obsèvasyon sa yo ki objektif?","Cheviy goch kliyan an anfle epi wouj","Kliyan an di l santi l toudi","Mwen panse li santi l poukont li","Li sanble parese","Yon obsèvasyon objektif se sa w ka wè oswa mezire. Sa kliyan an di se subjektif; opinyon pa obsèvasyon."],["Which of these is an objective observation?","The client's left ankle is swollen and red","The client says she feels dizzy","I think he is lonely","She seems lazy","An objective observation is something you can see or measure. What the client says is subjective; opinions are not observations."]]],"check":["h201","h202","h203","h204","h205"]},{"ch":3,"cfr":"(b)(3)(iii)","observed":true,"title":["Tanperati, pou ak respirasyon","Temperature, pulse and respiration"],"src":["S6","S12","S1"],"sections":[{"h":["Poukisa siy vital yo enpòtan","Why vital signs matter"],"src":["S1"],"b":[["p","Tanperati, pou ak respirasyon montre kijan kò a ap travay. Ou mezire yo, ou ekri yo touswit, epi ou rapòte sa ki pa nòmal oswa ki chanje pou kliyan sa a.","Temperature, pulse and respiration show how the body is working. You measure them, write them down right away, and report anything abnormal or changed for this client."],["li","Se youn nan konpetans enfimyè a dwe gade w fè pandan evalyasyon an.","This is one of the skills the nurse must watch you perform during the evaluation."]]},{"h":["Tanperati","Temperature"],"src":["S1"],"b":[["li","Nòmal pou yon granmoun: anviwon 98.6°F (37°C). Li ka varye yon ti kras pandan jounen an.","Normal for an adult: about 98.6°F (37°C). It can vary a little during the day."],["li","Rapòte 100.4°F (38°C) oswa plis, oswa yon tanperati ki pi ba pase sa ki nòmal pou kliyan an.","Report 100.4°F (38°C) or higher, or a temperature lower than the client's normal."],["li","Nan bouch: tann omwen 15 minit apre kliyan an fin manje, bwè oswa fimen.","By mouth: wait at least 15 minutes after the client eats, drinks or smokes."],["li","Lòt kote: nan zòrèy, sou fwon, oswa anba bra. Anba bra bay yon chif ki pi ba. Swiv enstriksyon tèmomèt la epi ekri ki kote w pran l.","Other sites: ear, forehead or armpit. The armpit reads lower. Follow the thermometer's instructions and write down which site you used."],["li","Sèvi ak yon kouvèti pwòp sou tèmomèt la chak fwa, epi netwaye l apre.","Use a clean probe cover every time, and clean the thermometer afterward."]]},{"h":["Pou","Pulse"],"src":["S1"],"b":[["li","Pou radyal la sou bò pous ponyèt la. Sèvi ak 2 oswa 3 dwèt, pa janm pous ou: pous ou gen pwòp pou pa l.","The radial pulse is on the thumb side of the wrist. Use 2 or 3 fingers, never your thumb: your thumb has its own pulse."],["li","Konte pandan 60 segonn, oswa jan ajans ou mande. Si l pa regilye, konte 60 segonn konplè epi rapòte l.","Count for 60 seconds, or as your agency requires. If it is irregular, count a full 60 seconds and report it."],["li","Nòmal pou yon granmoun k ap repoze: 60 a 100 batman pa minit. Note si l regilye, fò oswa fèb.","Normal for a resting adult: 60 to 100 beats per minute. Note whether it is regular, strong or weak."]]},{"h":["Respirasyon","Respiration"],"src":["S1"],"b":[["li","Yon respirasyon = pwatrin nan monte yon fwa epi desann yon fwa.","One respiration = the chest rises once and falls once."],["li","Konte touswit apre pou a, ak dwèt ou toujou sou ponyèt la. Si kliyan an konnen w ap konte respirasyon l, li ka chanje fason l respire.","Count right after the pulse, with your fingers still on the wrist. If the client knows you are counting breaths, they may change how they breathe."],["li","Nòmal pou yon granmoun: 12 a 20 respirasyon pa minit. Note si l gen difikilte pou respire oswa si l fè bri.","Normal for an adult: 12 to 20 breaths per minute. Note any difficulty breathing or noisy breathing."]]},{"h":["Ekri ak rapòte","Recording and reporting"],"src":["S12"],"b":[["li","Ekri chif yo touswit, ak lè a. Pa janm devine yon chif.","Write the numbers down right away, with the time. Never guess a number."],["li","Si w pa sèten, mezire ankò. Si l toujou pa nòmal, rapòte l bay enfimyè a.","If you are not sure, measure again. If it is still abnormal, report it to the nurse."]]},{"h":["Tansyon","Blood pressure"],"src":["S18"],"b":[["p","Règ federal la mande tanperati, pou ak respirasyon. Anpil ajans ak eta fòme ed yo pou tansyon tou: pran l sèlman si plan swen an mande l epi w fòme pou sa.","The federal rule lists temperature, pulse and respiration. Many agencies and states also train aides on blood pressure: take it only if the care plan calls for it and you are trained."],["li","Ekri de chif yo: sistolik (anwo) ak dyastolik (anba), egzanp 120/80.","Record both numbers: systolic (top) and diastolic (bottom), for example 120/80."],["li","Rapòte touswit yon tansyon 180/120 oswa plis (oswa youn nan de chif yo pi wo). Rele 911 si gen doulè nan pwatrin, souf kout oswa siy estwòk.","Report right away a reading of 180/120 or higher (either number). Call 911 if there is chest pain, shortness of breath or stroke signs."],["li","Rapòte tou nenpòt chif ki pi ba oswa pi wo pase limit plan swen an bay.","Also report any reading outside the limits in the care plan."]]}],"terms":[["vital signs","siy vital"],["temperature","tanperati"],["radial pulse","pou radyal"],["respiration","respirasyon"],["irregular","pa regilye"],["probe cover","kouvèti tèmomèt"]],"skills":[{"title":["Pran tanperati nan bouch (tèmomèt dijital)","Taking an oral temperature (digital)"],"steps":[["Lave men w, prezante w, epi eksplike sa w pral fè.","Clean your hands, introduce yourself, and explain what you will do."],["Mande si l manje, bwè oswa fimen nan 15 dènye minit yo. Si wi, tann.","Ask whether they ate, drank or smoked in the last 15 minutes. If so, wait."],["Mete yon kouvèti pwòp sou tèmomèt la, epi mete l anba lang lan, sou kote.","Put a clean probe cover on, and place it under the tongue, to one side."],["Mande kliyan an fèmen bouch li epi tann siyal tèmomèt la.","Ask the client to close their lips and wait for the thermometer's signal."],["Li chif la, jete kouvèti a, netwaye tèmomèt la, epi ekri tanperati a ak lè a.","Read the number, discard the cover, clean the thermometer, and record the temperature and time."],["Lave men w. Rapòte 100.4°F oswa plis bay enfimyè a.","Clean your hands. Report 100.4°F or higher to the nurse."]],"note":["Toujou swiv enstriksyon fabrikan tèmomèt la.","Always follow the thermometer maker's instructions."]},{"title":["Pou radyal ak respirasyon","Radial pulse and respirations"],"steps":[["Lave men w epi eksplike sa w pral fè.","Clean your hands and explain what you will do."],["Mete 2 oswa 3 dwèt sou bò pous ponyèt la. Konte batman yo pandan 60 segonn.","Place 2 or 3 fingers on the thumb side of the wrist. Count the beats for 60 seconds."],["San w pa retire dwèt ou, gade pwatrin nan epi konte respirasyon yo pandan 60 segonn.","Without moving your fingers, watch the chest and count breaths for 60 seconds."],["Ekri pou a ak respirasyon an touswit, ak lè a.","Record the pulse and respirations right away, with the time."],["Lave men w. Rapòte yon pou anba 60 oswa plis pase 100, oswa respirasyon ki pa nòmal.","Clean your hands. Report a pulse under 60 or over 100, or abnormal breathing."]],"note":["Pa itilize pous ou pou pran pou.","Do not use your thumb to take a pulse."]}],"qs":[["h301",1,["respiration","respirasyon"],["Ki nivo respirasyon nòmal pou yon granmoun k ap repoze?","6 a 10 pa minit","12 a 20 pa minit","24 a 30 pa minit","30 a 40 pa minit","Yon granmoun k ap repoze respire nòmalman 12 a 20 fwa pa minit."],["What is a normal resting respiration rate for an adult?","6 to 10 per minute","12 to 20 per minute","24 to 30 per minute","30 to 40 per minute","A resting adult normally breathes 12 to 20 times per minute."]]],"check":["h301","h302","h303","h304","h305"]},{"ch":4,"cfr":"(b)(3)(iv)","title":["Kontwòl enfeksyon lakay kliyan an","Infection control in the client's home"],"src":["S6","S1","S2","S3","S4","S11"],"sections":[{"h":["Poukisa sa diferan lakay moun","Why it is different in a home"],"src":["S6","S1"],"b":[["p","Nan yon kay, pa gen yon ekip netwayaj oswa yon depo ekipman bò kote w. Ou ka vizite plizyè kliyan nan yon jou, kidonk ou ka pote mikwòb de yon kay a yon lòt si w pa fè atansyon.","In a home, there is no cleaning crew or supply room nearby. You may visit several clients in one day, so you can carry germs from one home to the next if you are not careful."],["li","Pote pwòp pwovizyon ou: gan, dezenfektan men, savon, sèvyèt papye ak sak plastik.","Bring your own supplies: gloves, hand sanitizer, soap, paper towels and plastic bags."],["li","Mete sak ou sou yon sifas pwòp ak sèk, pa atè ni sou kabann kliyan an.","Set your bag on a clean, dry surface, not on the floor or the client's bed."],["li","Swiv plan swen an pou prekosyon espesyal kliyan an bezwen.","Follow the care plan for any special precautions the client needs."]]},{"h":["Chèn enfeksyon an, an kout","The chain of infection, in short"],"src":["S1"],"b":[["p","Enfeksyon pase nan sis maiyon: mikwòb la, kote l viv (rezèvwa), kote l soti, kijan l vwayaje, kote l antre, ak yon moun ki fasil pran l. Kase yon sèl maiyon, enfeksyon an rete. Maiyon ou kontwole plis la se kijan l vwayaje: men w, ekipman w ak twal yo.","Infection travels through six links: the germ, where it lives (reservoir), how it leaves, how it travels, where it enters, and a person who catches it easily. Break one link and the infection stops. The link you control most is how it travels: your hands, your equipment and linens."]]},{"h":["Ijyèn men lakay kliyan","Hand hygiene in the home"],"src":["S3"],"b":[["li","Netwaye men w lè w rive, anvan ak apre chak swen, anvan w prepare manje, apre w manyen fatra oswa twal sal, ak anvan w kite kay la.","Clean your hands when you arrive, before and after each care task, before preparing food, after handling trash or soiled laundry, and before you leave."],["li","Sèvi ak savon ak dlo lè men w sal yon fason ou ka wè, epi lè kliyan an gen dyare (tankou C. diff). Lòt fwa, dezenfektan ki gen omwen 60% alkòl bon.","Use soap and water when your hands are visibly soiled and when the client has diarrhea (such as C. diff). Otherwise, sanitizer with at least 60% alcohol works."],["li","CDC aksepte 15 a 20 segonn fwote ak savon. Pratike 20 segonn: anpil tès konpetans mande sa.","CDC accepts 15 to 20 seconds of scrubbing with soap. Practice 20 seconds, since many skills tests require it."],["li","Si pa gen savon oswa sèvyèt papye nan kay la, sèvi ak pa w. Pa seche men w ak sèvyèt twal fanmi an.","If the home has no soap or paper towels, use your own. Do not dry your hands on the family's cloth towel."]]},{"h":["Gan ak lòt PPE","Gloves and other PPE"],"src":["S2","S4"],"b":[["p","Mete gan chak fwa w ka touche san, likid kò, po ki blese oswa bagay ki sal ak likid kò. Chanje gan ant travay sal ak travay pwòp, epi lave men w apre w retire yo.","Wear gloves any time you might touch blood, body fluids, broken skin or items soiled with body fluids. Change gloves between dirty and clean tasks, and clean your hands after you take them off."],["p","Si plan swen an mande plis PPE, swiv lòd CDC a. Mete: rad izolasyon, mask, linèt, gan. Retire: gan, linèt, rad izolasyon, mask, epi ijyèn men.","If the care plan calls for more PPE, follow the CDC order. Putting on: gown, mask, goggles, gloves. Taking off: gloves, goggles, gown, mask, then hand hygiene."],["li","Ofri kliyan ki touse yon mouchwa papye, epi ankouraje l kouvri bouch li. Mete yon mask si plan swen an mande l.","Offer a coughing client a tissue and encourage them to cover their mouth. Wear a mask if the care plan calls for it."]]},{"h":["Twal sal, fatra ak zegwi","Laundry, trash and needles"],"src":["S1","S11"],"b":[["li","Kenbe twal sal lwen inifòm ou. Pa souke yo. Mete yo dirèk nan yon sak oswa nan machin lave a.","Hold soiled linens away from your uniform. Do not shake them. Put them straight into a bag or the washer."],["li","Mete fatra ki gen likid kò nan yon sak ki fèmen anvan w jete l.","Put trash with body fluids in a closed bag before throwing it out."],["li","Zegwi kliyan an (tankou pou ensilin) ale dirèk nan yon bwat zegwi (sharps container). Pa janm remete kapsil sou yon zegwi.","The client's needles (for example, for insulin) go straight into a sharps container. Never recap a needle."],["li","Pa ranpli bwat zegwi a plis pase anviwon twa ka, epi kenbe l lwen timoun ak bèt. Avèti sipèvizè w lè l prèske plen: yo jete l dapre règ lokal yo.","Do not fill the sharps container past about three-quarters, and keep it away from children and pets. Tell your supervisor when it is nearly full; it is disposed of by local rules."]]},{"h":["Netwaye ak dezenfekte","Cleaning and disinfecting"],"src":["S2"],"b":[["li","Travay depi zòn pwòp rive nan zòn sal, pou w pa pote mikwòb sou sifas ki pwòp.","Work from clean areas to dirty areas so you do not spread germs onto clean surfaces."],["li","Netwaye sifas yo touche souvan: manch pòt, ba kabann, telekòmand, twalèt.","Clean surfaces people touch often: doorknobs, bed rails, remote controls, the bathroom."],["li","Li etikèt dezenfektan an. Kite sifas la mouye pandan tan etikèt la mande.","Read the disinfectant label. Leave the surface wet for the time the label says."]]},{"h":["Siy enfeksyon pou w rapòte","Signs of infection to report"],"src":["S1"],"b":[["li","Wouj, cho, anfle, doulè, oswa likid jòn oswa vèt nan yon blesi.","Redness, warmth, swelling, pain, or yellow or green drainage from a wound."],["li","Lafyèv (100.4°F oswa plis), touse ki fèk parèt, souf kout.","Fever (100.4°F or higher), a new cough, shortness of breath."],["li","Pipi twoub, ak san, ak move sant, oswa ki brile.","Urine that is cloudy, bloody, foul-smelling or burning."],["li","Granmoun ka pa gen lafyèv: yon konfizyon ki fèk parèt oswa yon feblès toudenkou ka sèl siy lan.","Older adults may have no fever: new confusion or sudden weakness may be the only sign."],["p","Ou pa fè dyagnostik e ou pa bay medikaman. Rapòte touswit bay sipèvizè w oswa enfimyè a, epi ekri sa w wè.","You do not diagnose and you do not give medication. Report right away to your supervisor or the nurse, and write down what you saw."]]}],"terms":[["standard precautions","prekosyon estanda"],["soiled linen","twal sal"],["sharps container","bwat zegwi"],["recap (a needle)","remete kapsil (sou zegwi)"],["disinfectant","dezenfektan"],["contact time","tan kontak"]],"skillRefs":["handwashing"],"qs":[["hha13",0,["hand hygiene","ijyèn men"],["Ou vizite twa kliyan pa jou. Ki lè ou dwe netwaye men w?","Lè w rive, anvan ak apre swen, epi anvan w kite chak kay","Sèlman lè w rive lakay premye kliyan nan jounen an","Sèlman si men w sal","Sèlman nan fen jounen an, apre dènye vizit ou","Ou se pon ant kay yo. Netwaye men w lè w rive, anvan ak apre swen, epi anvan w kite chak kay, pou mikwòb pa vwayaje avè w."],["You visit three clients a day. When should you clean your hands?","When you arrive, before and after care, and before leaving each home","Only when you arrive at the first client's home of the day","Only if your hands look dirty","Only at the end of the day, after your last visit","You are the link between homes. Clean your hands when you arrive, before and after care, and before leaving each home, so germs do not travel with you."]],["hha14",1,["soiled linen","twal sal"],["W ap chanje dra sal yon kliyan. Kijan pou w manyen yo?","Souke yo pou retire sa ki sou yo","Kenbe yo lwen inifòm ou epi pa souke yo","Kenbe yo kole sou ou pou yo pa tonbe","Mete yo atè anvan w ranmase yo","Kenbe twal sal lwen rad ou, pa souke yo paske sa voye mikwòb nan lè a, epi mete yo dirèk nan yon sak oswa nan machin lave a."],["You are changing a client's soiled sheets. How should you handle them?","Shake them out to remove debris","Hold them away from your uniform and do not shake them","Hold them close so they do not fall","Put them on the floor before picking them up","Keep soiled linens away from your clothes, do not shake them because that spreads germs into the air, and put them straight into a bag or the washer."]],["hha15",2,["sharps container","bwat zegwi"],["Bwat zegwi (sharps container) kliyan an prèske plen a twa ka. Kisa ou fè?","Peze zegwi yo desann pou veso a ka pran plis","Vide l nan poubèl kwizin nan epi kontinye sèvi avè l","Pa ranpli l plis; avèti sipèvizè w pou yo ranplase l","Mete kapsil yo tounen sou zegwi yo","FDA di pa ranpli yon bwat zegwi plis pase anviwon twa ka, epi jete l dapre règ lokal yo. Pa janm remete kapsil sou yon zegwi. Avèti sipèvizè w."],["The client's sharps container is about three-quarters full. What do you do?","Push the needles down so the container can hold more","Empty it into the kitchen trash and keep using it","Stop filling it and tell your supervisor so it can be replaced","Put the caps back on the needles","The FDA says not to fill a sharps container past about three-quarters, and to dispose of it by local rules. Never recap a needle. Tell your supervisor."]],["hha16",0,["clean to dirty","pwòp rive nan sal"],["Lè w ap netwaye twalèt kliyan an, nan ki lòd ou travay?","Depi zòn ki pi pwòp yo rive nan zòn ki pi sal yo","Depi zòn ki pi sal yo rive nan zòn ki pi pwòp yo","Nenpòt lòd","Sèlman zòn ki sanble sal","Travay depi pwòp rive nan sal pou w pa pote mikwòb sou sifas ki deja pwòp. Kite dezenfektan an rete mouye pandan tan ki ekri sou etikèt la."],["When cleaning the client's bathroom, in what order do you work?","From the cleanest areas to the dirtiest","From the dirtiest areas to the cleanest","Any order","Only areas that look dirty","Work from clean to dirty so you do not spread germs onto clean surfaces. Leave the disinfectant wet for the contact time on its label."]],["hha17",1,["report","rapòte"],["Kliyan w lan, ki gen 80 an, konfonn depi maten epi li di li gen brili lè l ap pipi. Kisa ou fè?","Ba l ji pou l bwè epi tann demen","Rapòte sa bay sipèvizè w oswa enfimyè a touswit","Pa di anyen paske li pa gen lafyèv","Ba l yon grenn ou jwenn lakay la","Konfizyon ki fèk parèt ak brili lè l ap pipi ka siy yon enfeksyon, menm san lafyèv. Ou pa fè dyagnostik: ou rapòte touswit."],["Your 80-year-old client has been confused since this morning and says it burns when she urinates. What do you do?","Give her juice and wait until tomorrow","Report it to your supervisor or the nurse right away","Say nothing because she has no fever","Give her a pill you find in the house","New confusion and burning on urination can be signs of infection, even without a fever. You do not diagnose: you report right away."]],["hha8",0,["body fluids","likid kò"],["Ki lè pou w mete gan ak yon kliyan?","Lè w ka touche san, likid kò oswa po ki blese","Sèlman lè kliyan an gen lafyèv oswa l ap touse","Sèlman lè w ap fè manje","Janm lakay moun, sèlman nan lopital oswa mezon retrèt","Mete gan chak fwa w ka touche san, pipi, poupou, vomi oswa po ki blese. Lave men w anvan ak apre."],["When should you wear gloves with a client?","When you may touch blood, body fluids or broken skin","Only when the client has a fever or a cough","Only when cooking","Never in a home, only in a hospital or nursing home","Wear gloves any time you might touch blood, urine, stool, vomit or broken skin. Clean your hands before and after."]],["h401",2,["supply bag","sak pwovizyon"],["Lè w rive lakay kliyan an, ki kote pou w mete sak pwovizyon ou?","Atè bò pòt la","Sou kabann kliyan an","Sou yon sifas pwòp ak sèk","Nan twalèt la","Mete sak ou sou yon sifas pwòp ak sèk pou l pa ranmase mikwòb ou ta pote nan pwochen kay la."],["When you arrive at a client's home, where should you set your supply bag?","On the floor by the door","On the client's bed","On a clean, dry surface","In the bathroom","Set your bag on a clean, dry surface so it does not pick up germs you would carry to the next home."]],["h402",3,["cough etiquette","kouvri touse"],["Kliyan w lan touse anpil. Ki ijyèn respiratwa ki apwopriye?","Pa okipe l, paske touse nòmal pou anpil kliyan","Fèmen tout fenèt yo epi monte chalè a pou touse a sispann","Ba kliyan an medikaman pou touse ki soti famasi epi ekri l","Ofri l mouchwa papye, ankouraje l kouvri bouch li, epi mete mask si plan swen an mande l","Ijyèn respiratwa fè pati prekosyon estanda: kouvri touse, jete mouchwa, lave men, mask si plan swen an mande l."],["Your client is coughing a lot. What respiratory hygiene is appropriate?","Ignore it, since a cough is normal for many clients","Close all the windows and turn the heat up to stop the cough","Give the client cough medicine from the pharmacy and write it down","Offer tissues, encourage covering the mouth, and wear a mask if the care plan calls for it","Respiratory hygiene is part of standard precautions: cover coughs, throw tissues away, clean hands, and mask if the care plan calls for it."]],["h403",0,["chain of infection","chèn enfeksyon"],["Ki maiyon nan chèn enfeksyon an ou kontwole plis nan travay ou chak jou?","Kijan mikwòb la vwayaje: men w, ekipman w ak twal yo","Mikwòb la limenm","Kote mikwòb la viv (rezèvwa)","Fòs kò kliyan an pou l goumen ak enfeksyon","Ou pa ka chanje mikwòb la ni kò kliyan an, men ou kontwole kijan l vwayaje. Men pwòp, ekipman pwòp ak twal ou manyen byen kase chèn nan."],["Which link in the chain of infection can you control most in your daily work?","How germs travel: your hands, equipment and linens","The germ itself","Where the germ lives (reservoir)","The client's ability to fight infection","You cannot change the germ or the client's body, but you control how germs travel. Clean hands, clean equipment and careful handling of linens break the chain."]],["h404",1,["break the chain","kase chèn nan"],["Kisa k rive lè w kase yon sèl maiyon nan chèn enfeksyon an?","Anyen; fòk ou kase tout sis maiyon yo","Enfeksyon an rete, li pa gaye","Mikwòb la vin pi fò","Se sèlman fanmi an ki pwoteje","Chak maiyon bezwen lòt yo. Kase yon sèl, tankou lave men w, epi enfeksyon an pa ka pase."],["What happens when you break one link in the chain of infection?","Nothing; you must break all six links","The infection stops spreading","The germ becomes stronger","Only the family is protected","Each link needs the others. Break just one, for example by cleaning your hands, and the infection cannot pass on."]],["h405",2,["C. diff","C. diff"],["Kliyan w lan gen dyare ki soti nan C. diff. Kijan pou w netwaye men w apre swen an?","Sèlman ak dezenfektan men ki gen alkòl","Siye yo ak yon sèvyèt papye","Lave yo ak savon ak dlo","Gan yo ase; pa bezwen netwaye men w","Lè kliyan an gen dyare tankou C. diff, oswa lè men w sal yon fason ou ka wè, lave yo ak savon ak dlo. Dezenfektan alkòl pa ase nan ka sa a."],["Your client has diarrhea from C. diff. How should you clean your hands after care?","With alcohol hand sanitizer only","Wipe them on a paper towel","Wash them with soap and water","Gloves are enough; no need to clean your hands","When the client has diarrhea such as C. diff, or your hands are visibly soiled, wash with soap and water. Alcohol sanitizer is not enough here."]],["h406",1,["hand sanitizer","dezenfektan men"],["Dezenfektan men an dwe gen omwen konbyen alkòl?","30%","60%","45%","Nenpòt kantite","Sèvi ak yon dezenfektan ki gen omwen 60% alkòl lè men w pa sal yon fason ou ka wè."],["Hand sanitizer must contain at least how much alcohol?","30%","60%","45%","Any amount","Use a sanitizer with at least 60% alcohol when your hands are not visibly soiled."]],["h407",3,["handwashing","lave men"],["Lè w ap lave men w ak savon, pandan konbyen tan pou w fwote?","5 segonn","10 segonn","Jiskaske dlo a vin cho","20 segonn","CDC aksepte 15 a 20 segonn. Pratike 20 segonn, paske anpil tès konpetans mande sa."],["When you wash your hands with soap, how long should you scrub?","5 seconds","10 seconds","Until the water gets warm","20 seconds","CDC accepts 15 to 20 seconds. Practice 20 seconds, since many skills tests require it."]],["h408",0,["change gloves","chanje gan"],["Ou fin netwaye kliyan an apre l fè pipi sou li, epi kounye a ou bezwen ede l abiye. Kisa ou fè ak gan ou yo?","Retire yo, netwaye men w, epi mete gan pwòp si w bezwen","Kenbe menm gan yo pou w pa pèdi tan ni gan","Lave gan yo ak savon epi kenbe yo","Mete gan pwòp sou gan sal yo epi kontinye","Chanje gan ant yon travay sal ak yon travay pwòp, epi netwaye men w chak fwa w retire gan. Sa anpeche mikwòb pase sou rad ak sifas pwòp."],["You finish cleaning the client after incontinence and now need to help them dress. What do you do with your gloves?","Take them off, clean your hands, and put on clean gloves if needed","Keep the same gloves on to save time and gloves","Wash the gloves with soap and keep them on","Put clean gloves on over the dirty ones and keep going","Change gloves between dirty and clean tasks, and clean your hands every time you take gloves off. This keeps germs off clean clothes and surfaces."]],["h409",2,["removing PPE","retire PPE"],["Ou gen rad izolasyon, mask, linèt ak gan sou ou. Kisa pou w retire an premye?","Mask la","Rad izolasyon an","Gan yo","Linèt yo","Dapre lòd CDC a, retire gan an premye, paske se yo ki pi sal. Apre sa linèt, rad izolasyon, mask, epi ijyèn men."],["You are wearing a gown, mask, goggles and gloves. What do you take off first?","The mask","The gown","The gloves","The goggles","Following the CDC order, gloves come off first because they are the most soiled. Then goggles, gown, mask, then hand hygiene."]],["h410",1,["recap (a needle)","remete kapsil (sou zegwi)"],["Ou jwenn yon zegwi ensilin kliyan an te itilize sou tab la. Kisa ou fè?","Remete kapsil la sou li epi jete l nan fatra","Mete l dirèk nan bwat zegwi a san w pa remete kapsil","Vlope l nan sèvyèt papye epi jete l","Kite l sou tab la pou enfimyè a","Pa janm remete kapsil sou yon zegwi: se konsa moun pike tèt yo. Mete l dirèk nan bwat zegwi a."],["You find the client's used insulin needle on the table. What do you do?","Put the cap back on and throw it in the trash","Put it straight into the sharps container without recapping it","Wrap it in a paper towel and throw it away","Leave it on the table for the nurse","Never recap a needle: that is how people stick themselves. Put it straight into the sharps container."]],["h411",3,["wound infection","enfeksyon blesi"],["Pandan beny lan, ou wè blesi kliyan an wouj, cho, epi gen likid jòn-vèt k ap soti. Kisa ou fè?","Netwaye l ak alkòl, kouvri l, epi gade l ankò pwochen vizit","Mete krèm antibyotik sou li","Tann kèk jou pou w wè si l ap geri pou kont li","Rapòte l bay enfimyè a touswit epi ekri sa w wè","Wouj, chalè, anflamasyon ak likid jòn oswa vèt se siy enfeksyon. Ou pa trete l e ou pa bay medikaman: ou rapòte touswit epi ou ekri sa w wè."],["During a bath, you see the client's wound is red, warm and has yellow-green drainage. What do you do?","Clean it with alcohol, cover it, and check it again next visit","Put antibiotic cream on it","Wait a few days to see if it gets better on its own","Report it to the nurse right away and write down what you saw","Redness, warmth, swelling and yellow or green drainage are signs of infection. You do not treat it or give medication: you report right away and write down what you saw."]]],"check":["hha13","hha14","hha15","hha16","hha17"]},{"ch":5,"cfr":"(b)(3)(v)","title":["Kijan kò a mache ak chanjman pou w rapòte","Body functions and changes to report"],"src":["S6","S1","S13"],"sections":[{"h":["Règ prensipal la","The main rule"],"src":["S6"],"b":[["p","Ou pa bezwen konnen tout maladi. Ou bezwen konnen sa ki nòmal pou kliyan sa a, epi rapòte nenpòt chanjman. Yon chanjman toudenkou pa janm «jis laj».","You do not need to know every disease. You need to know what is normal for this client, and report any change. A sudden change is never “just age.”"]]},{"h":["Sistèm kò a ak sa pou w rapòte","Body systems and what to report"],"src":["S1","S13"],"b":[["li","Respirasyon (poumon): souf kout, touse ki fèk parèt, sifleman, bouch oswa pwent dwèt ki vin ble. Souf kout ki grav = 911.","Breathing (lungs): shortness of breath, a new cough, wheezing, blue lips or fingertips. Severe shortness of breath = 911."],["li","Kè ak sikilasyon: doulè oswa presyon nan pwatrin = 911, epi apre sa rele ajans ou. Pye oswa cheviy ki anfle plis pase dabitid. Dwèt oswa zòtèy frèt, pal oswa ble.","Heart and circulation: chest pain or pressure = 911, then call your agency. Feet or ankles more swollen than usual. Cold, pale or blue fingers or toes."],["li","Dijesyon: pa gen apeti, kè plen, vomi, dyare, konstipasyon ki diferan de sa ki nòmal, poupou nwa oswa ak san.","Digestion: loss of appetite, nausea, vomiting, diarrhea, constipation that differs from normal, black or bloody stool."],["li","Pipi: pi piti pipi, pipi fonse, twoub, ak san oswa ki brile, oswa pipi sou li ki fèk kòmanse. Mwens pipi ak pipi fonse ka siy dezidratasyon (gade chapit 12).","Urine: less urine, dark, cloudy or bloody urine, burning, or new incontinence. Less urine and dark urine can be a sign of dehydration (see chapter 12)."],["li","Sèvo ak nè: konfizyon toudenkou, feblès sou yon bò, figi ki tonbe, pawòl ki melanje = 911 (siy estwòk).","Brain and nerves: sudden confusion, weakness on one side, a drooping face, slurred speech = 911 (stroke signs)."],["li","Misk ak zo: nouvo doulè, jwenti ki anfle. Si l pa ka kanpe sou yon janm apre yon tonbe, pa deplase l; rele 911.","Muscles and bones: new pain, a swollen joint. If they cannot stand on a leg after a fall, do not move them; call 911."],["li","Sans ak moral: chanjman nan je oswa nan tande, tristès ki fèk parèt, kliyan an izole tèt li, pa dòmi.","Senses and mood: changes in vision or hearing, new sadness, withdrawing from others, not sleeping."],["li","Po: wè chapit 13.","Skin: see chapter 13."]]},{"h":["Laj ak chanjman nòmal","Aging and normal changes"],"src":["S1"],"b":[["p","Avèk laj, kèk bagay ralanti: mouvman, dijesyon, tande. Men chanjman ki rive vit, nan kèk èdtan oswa kèk jou, toujou bezwen rapò.","With age, some things slow down: movement, digestion, hearing. But changes that happen quickly, over hours or days, always need to be reported."]]}],"terms":[["shortness of breath","souf kout"],["swelling (edema)","anflamasyon (edèm)"],["incontinence","pipi oswa poupou sou li"],["constipation","konstipasyon"],["stroke","estwòk (konjesyon serebral)"],["change in condition","chanjman nan kondisyon"]],"qs":[["h501",1,["swelling (edema)","anflamasyon (edèm)"],["Cheviy kliyan an pi anfle pase dabitid jodi a. Kisa ou fè?","Anyen, se nòmal ak laj","Rapòte l bay enfimyè a","Masaj cheviy yo fò","Ba l plis sèl","Yon anflamasyon ki ogmante se yon chanjman ou dwe rapòte."],["The client's ankles are more swollen than usual today. What do you do?","Nothing, it is normal with age","Report it to the nurse","Massage the ankles hard","Give more salt","Swelling that increases is a change you must report."]]],"check":["h501","h502","h503","h504","h505"]},{"ch":6,"cfr":"(b)(3)(vi)","title":["Yon kay pwòp, an sekirite ak an sante","A clean, safe and healthy home"],"src":["S6","S1","S2","S17"],"sections":[{"h":["Anpeche moun tonbe","Preventing falls"],"src":["S1"],"b":[["li","Retire tapi ki glise, fil elektrik ak bagay ki atè nan chemen yo.","Remove loose rugs, cords and clutter from walkways."],["li","Bon limyè nan koridò ak eskalye, ak ti limyè lannwit ant kabann ak twalèt.","Good lighting in halls and stairs, and night lights between the bed and the bathroom."],["li","Ba pou kenbe ak tapi ki pa glise nan twalèt.","Grab bars and a non-slip mat in the bathroom."],["li","Mete bagay kliyan an itilize souvan nan rive men l, ansanm ak telefòn nan.","Keep things the client uses often within reach, including the phone."],["li","Soulye ki pa glise. Siye dlo ak lòt bagay ki tonbe atè touswit.","Non-skid footwear. Wipe up spills right away."]]},{"h":["Sekirite kont dife ak brili","Fire and burn safety"],"src":["S1","S17"],"b":[["li","Detektè lafimen yo dwe mache. Rapòte si youn pa mache.","Smoke detectors must work. Report any that do not."],["li","Pa gen dife, bouji ni sigarèt toupre oksijèn.","No flames, candles or cigarettes near oxygen."],["li","Kenbe chofaj elektrik lwen dra, rido ak papye.","Keep space heaters away from bedding, curtains and paper."],["li","Vire manch chodyè yo anndan sou recho a.","Turn pot handles inward on the stove."],["li","Teste dlo beny lan anvan kliyan an antre, ak yon tèmomèt beny oswa anndan ponyèt ou. Granmoun boule fasil epi yo ka pa santi chalè byen.","Test bath water before the client gets in, with a bath thermometer or the inside of your wrist. Older adults burn easily and may not feel heat well."],["li","Ti dife lwil nan yon pwela: glise yon kouvèti oswa yon plato sou li, fèmen recho a, pa deplase pwela a, epi pa janm mete dlo.","Small grease fire in a pan: slide a lid or baking sheet over it, turn off the burner, do not move the pan, and never use water."],["li","Si gen dife: fè kliyan an soti, fèmen pòt yo dèyè w, epi rele 911 depi deyò.","If there is a fire: get the client out, close doors behind you, and call 911 from outside."]]},{"h":["Pwòpte ak pwodui chimik","Cleanliness and chemicals"],"src":["S2"],"b":[["li","Lave asyèt, siye kontwa, sòti fatra, epi tcheke frijidè a pou manje ki gate.","Wash dishes, wipe counters, take out the trash, and check the refrigerator for spoiled food."],["li","Kenbe pwodui netwayaj nan bwat orijinal yo, lwen manje.","Keep cleaning products in their original containers, away from food."],["li","Pa janm melanje kloròks (bleach) ak amonyak oswa ak lòt pwodui: sa fè gaz toksik.","Never mix bleach with ammonia or other cleaners: it makes toxic gas."]]},{"h":["Sekirite pa w","Your own safety"],"src":["S1"],"b":[["li","Konnen adrès egzak kote w ye pou w ka bay li si w rele 911.","Know the exact address where you are so you can give it if you call 911."],["li","Si w santi w pa an sekirite (yon moun vyolan, yon bèt agresif, zam), kite kay la epi rele ajans ou.","If you feel unsafe (a violent person, an aggressive animal, weapons), leave and call your agency."],["li","Sèvi ak bon mekanik kò lè w ap leve oswa deplase bagay.","Use good body mechanics when lifting or moving things."]]}],"terms":[["fall prevention","prevansyon tonbe"],["grab bar","ba pou kenbe"],["non-skid footwear","soulye ki pa glise"],["smoke detector","detektè lafimen"],["space heater","chofaj elektrik"],["toxic","toksik"]],"skills":[{"title":["Lis sekirite lakay","Home safety checklist"],"steps":[["Chemen yo pwòp: pa gen tapi ki glise, fil elektrik, oswa bagay atè.","Clear paths: no loose rugs, cords, or items on the floor."],["Bon limyè nan koridò ak eskalye, ak ti limyè lannwit.","Good lighting in halls and stairs, plus night lights."],["Nan twalèt: ba pou kenbe ak tapi ki pa glise.","In the bathroom: grab bars and a non-slip mat."],["Detektè lafimen yo mache. Pa gen dife toupre oksijèn.","Smoke detectors work. No flames near oxygen."],["Pwodui netwayaj nan bwat orijinal yo, lwen manje.","Cleaning products in their original containers, away from food."],["Nimewo ijans yo ak adrès kay la ekri toupre telefòn nan.","Emergency numbers and the home address are written near the phone."]],"note":["Si w wè yon danje ou pa ka ranje, rapòte l bay sipèvizè w.","If you see a hazard you cannot fix, report it to your supervisor."]}],"qs":[["h601",3,["bleach","kloròks"],["Ki melanj pwodui netwayaj ki danjere?","Savon ak dlo","Vinèg ak dlo","Dezenfektan ak dlo jan etikèt la di","Kloròks ak amonyak","Kloròks ak amonyak fè yon gaz toksik. Pa janm melanje pwodui netwayaj."],["Which mix of cleaning products is dangerous?","Soap and water","Vinegar and water","Disinfectant and water as the label says","Bleach and ammonia","Bleach and ammonia make a toxic gas. Never mix cleaning products."]]],"check":["h601","h602","h603","h604","h605"]},{"ch":7,"cfr":"(b)(3)(vii)","title":["Rekonèt ijans epi aji","Recognizing and handling emergencies"],"src":["S6","S13","S32","S1"],"sections":[{"h":["Premye etap yo","First steps"],"src":["S1"],"b":[["n","Rete kalm epi asire w kote a san danje pou ou ak kliyan an.","Stay calm and make sure the scene is safe for you and the client."],["n","Pou yon ijans ki menase lavi, rele 911 an premye. Bay adrès egzak la, sa k pase, ak kondisyon kliyan an. Rete sou liy lan.","For a life-threatening emergency, call 911 first. Give the exact address, what happened, and the client's condition. Stay on the line."],["n","Pa kite kliyan an poukont li.","Do not leave the client alone."],["n","Rele ajans ou osito w kapab, epi ekri sa k te pase.","Call your agency as soon as you can, and write down what happened."],["p","Ajans ou gen yon plan pou ijans. Konnen sa plan swen kliyan an di pou ijans.","Your agency has an emergency plan. Know what the client's care plan says about emergencies."]]},{"h":["Toufe","Choking"],"src":["S32","S1"],"b":[["li","Siy: moun nan kenbe gòj li, li pa ka pale, li respire ak bri, touse fèb, oswa po l vin ble.","Signs: the person grabs their throat, cannot speak, breathes noisily, coughs weakly, or turns blue."],["li","Mande: «W ap toufe? Ou ka pale?» Si l ka touse fò oswa pale, ankouraje l kontinye touse.","Ask: “Are you choking? Can you speak?” If they can cough hard or speak, encourage them to keep coughing."],["li","Si l pa ka pale ni respire byen, epi ou fòme pou sa: 5 kou nan do ant zo zepòl yo, epi 5 pouse nan vant (Heimlich). Kontinye jiskaske bagay la soti.","If they cannot speak or breathe well and you are trained: 5 back blows between the shoulder blades, then 5 abdominal thrusts (Heimlich). Repeat until the object comes out."],["li","Si l pèdi konesans: rele 911, kouche l sou yon sifas plat, epi kòmanse CPR si w fòme.","If they become unconscious: call 911, lay them on a flat surface, and start CPR if you are trained."]]},{"h":["Estwòk: B.E. F.A.S.T.","Stroke: B.E. F.A.S.T."],"src":["S13"],"b":[["li","B (Balans): li toudi oswa li pèdi balans?","B (Balance): are they dizzy or off balance?"],["li","E (Je): li gen pwoblèm pou l wè?","E (Eyes): do they have trouble seeing?"],["li","F (Figi): mande l souri. Èske yon bò figi a tonbe?","F (Face): ask them to smile. Does one side droop?"],["li","A (Bra): mande l leve de bra yo. Èske youn desann?","A (Arms): ask them to raise both arms. Does one drift down?"],["li","S (Pawòl): mande l repete yon fraz. Èske pawòl yo melanje oswa dwòl?","S (Speech): ask them to repeat a phrase. Is it slurred or strange?"],["li","T (Tan): rele 911 touswit epi note ki lè siy yo te kòmanse.","T (Time): call 911 right away and note when the signs started."]]},{"h":["Lòt ijans","Other emergencies"],"src":["S1","S13"],"b":[["li","Kriz kadyak: doulè oswa presyon nan pwatrin, doulè nan bra, machwè oswa do, souf kout, swe frèt, kè plen. Rele 911.","Heart attack: chest pain or pressure, pain in the arm, jaw or back, shortness of breath, cold sweat, nausea. Call 911."],["li","Tonbe: pa leve kliyan an poukont ou. Gade si l blese, rele enfimyè a oswa 911 si l blese, kenbe l cho ak konfòtab, epi rapòte tonbe a menm si l pa blese.","Fall: do not lift the client by yourself. Check for injury, call the nurse or 911 if injured, keep them warm and comfortable, and report the fall even with no injury."],["li","Kriz (seizure): pwoteje tèt li, retire bagay ki ka blese l, pa kenbe l fò, pa mete anyen nan bouch li, epi gade lè a. Apre sa, vire l sou kote. Rele 911 si kriz la dire plis pase 5 minit.","Seizure: protect their head, move objects away, do not hold them down, put nothing in their mouth, and time it. Afterward, turn them on their side. Call 911 if it lasts more than 5 minutes."],["li","Sik ba (dyabèt): tranble, swe, konfizyon, kè bat vit. Swiv plan swen an epi rapòte; rele 911 si l pa reponn.","Low blood sugar (diabetes): shaky, sweaty, confused, fast heartbeat. Follow the care plan and report; call 911 if they do not respond."],["li","San k ap koule: mete gan, peze dirèkteman sou blesi a ak yon twal pwòp.","Bleeding: put on gloves and press directly on the wound with a clean cloth."],["li","Brili: mete l anba dlo frèt k ap koule (pa glas), epi rapòte l.","Burns: cool under running cool water (not ice), and report it."]]}],"terms":[["emergency","ijans"],["choking","toufe"],["abdominal thrusts","pouse nan vant (Heimlich)"],["stroke","estwòk"],["seizure","kriz (malkadi)"],["low blood sugar","sik ba"],["unconscious","pèdi konesans"]],"skills":[{"title":["Repons pou yon moun k ap toufe","Responding to choking"],"steps":[["Mande: «W ap toufe? Ou ka pale?»","Ask: “Are you choking? Can you speak?”"],["Si l ka touse fò, ankouraje l kontinye touse. Rete avè l.","If they can cough hard, encourage them to keep coughing. Stay with them."],["Si l pa ka pale ni respire, rele pou èd epi fè yon moun rele 911.","If they cannot speak or breathe, shout for help and have someone call 911."],["Si w fòme: 5 kou nan do ant zo zepòl yo, apre sa 5 pouse nan vant, anwo lonbrit la.","If trained: 5 back blows between the shoulder blades, then 5 abdominal thrusts just above the navel."],["Si l pèdi konesans: kouche l atè, rele 911, epi kòmanse CPR si w fòme.","If they become unconscious: lower them to the floor, call 911, and start CPR if trained."]],"note":["Menm si bagay la soti, moun nan dwe wè yon pwofesyonèl sante. Rapòte l bay ajans ou.","Even if the object comes out, the person should see a health care provider. Report it to your agency."]},{"title":["Rele 911","Calling 911"],"steps":[["Di adrès egzak la, ak apatman oswa etaj la.","Give the exact address, including the apartment or floor."],["Di sa k pase ak kondisyon kliyan an kounye a.","Say what happened and the client's condition right now."],["Bay non w epi di w se ed swen a domisil.","Give your name and say you are a home health aide."],["Reponn kesyon yo epi swiv enstriksyon yo. Pa rakwoche anvan yo di w.","Answer their questions and follow their instructions. Do not hang up until they tell you."],["Apre sa, rele ajans ou epi ekri sa k te pase ak lè a.","Afterward, call your agency and write down what happened and when."]],"note":["Kenbe adrès kliyan an sou ou chak vizit.","Keep the client's address with you at every visit."]}],"qs":[["h701",1,["choking","toufe"],["Kliyan an kòmanse touse fò pandan l ap manje, men li ka pale. Kisa ou fè?","Fè presyon nan vant touswit, anvan sa vin pi mal","Ankouraje l kontinye touse epi rete avè l","Ba l yon gwo vè dlo pou l bwè vit","Frape do l fò touswit","Si moun nan ka touse fò oswa pale, pa entèvni. Ankouraje l touse; yon touse fò ka fè bagay la soti."],["The client starts coughing hard while eating but can speak. What do you do?","Give abdominal thrusts right away, before it gets worse","Encourage them to keep coughing and stay with them","Give them a big glass of water to drink quickly","Hit their back hard right away","If the person can cough hard or speak, do not intervene. Encourage coughing; a strong cough can clear the object."]]],"check":["h701","h702","h703","h704","h705"]},{"ch":8,"cfr":"(b)(3)(viii)","title":["Bezwen kliyan an, dwa l ak pwoteksyon kont abi","Client needs, rights and protection from abuse"],"src":["S6","S12","S1"],"sections":[{"h":["Respè pou moun nan ak byen l","Respect for the person and their property"],"src":["S12"],"b":[["p","Kliyan an gen dwa pou yo trete l ak respè, li menm ak byen l. Pandan vizit ou, pa kase, pa deplase, pa pran anyen ki pou li, anndan kou deyò kay la.","The client has the right to have their person and property treated with respect. During your visits, do not damage, misplace or take anything that belongs to them, inside or outside the home."],["li","Kliyan an se yon patnè nan swen l. Respekte preferans li, tankou lè vizit yo, dapre plan swen an.","The client is a partner in their care. Respect their preferences, such as visit times, within the plan of care."],["li","Si w pral an reta oswa orè a chanje, avèti ajans ou pou yo ka avèti kliyan an.","If you will be late or the schedule changes, tell your agency so the client is informed."],["li","Respekte kilti, relijyon ak fason kliyan an renmen fè bagay yo.","Respect the client's culture, religion and the way they like things done."]]},{"h":["Bezwen fizik, emosyonèl ak devlopman","Physical, emotional and developmental needs"],"src":["S6","S1"],"b":[["li","Bezwen fizik: manje, dlo, pwòpte, repo, sekirite, soulajman doulè.","Physical needs: food, fluids, hygiene, rest, safety, pain relief."],["li","Bezwen emosyonèl: respè, konpayi, santi l itil, kontwole pwòp lavi l.","Emotional needs: respect, company, feeling useful, control over their own life."],["li","Ankouraje kliyan an fè sa l kapab pou kont li. Sa kenbe fòs li ak diyite l.","Encourage the client to do what they can for themselves. It keeps their strength and dignity."],["li","Moun ki gen demans: pale dousman, bay yon sèl enstriksyon alafwa, pa diskite, epi reponn ak kalm menm si l poze menm kesyon an plizyè fwa.","People with dementia: speak calmly, give one instruction at a time, do not argue, and answer calmly even if they ask the same question many times."],["li","Si yon moun ki gen demans fache oswa akize w (pa egzanp, di ou vòlè yon bagay): rete kalm, rekonèt santiman l, ofri ede l chèche, epi chanje sijè a dousman. Pa diskite. Rapòte akizasyon an bay sipèvizè w.","If a person with dementia becomes upset or accuses you (for example, says you stole something): stay calm, acknowledge the feeling, offer to help look, and gently redirect. Do not argue. Report the accusation to your supervisor."]]},{"h":["Vi prive pandan swen","Privacy during care"],"src":["S1"],"b":[["li","Frape anvan w antre epi tann repons.","Knock before entering and wait for an answer."],["li","Fèmen pòt ak rido pandan swen pèsonèl.","Close doors and curtains during personal care."],["li","Dekouvri sèlman pati kò w ap lave a. Kenbe rès kò a kouvri.","Uncover only the part of the body you are washing. Keep the rest covered."]]},{"h":["Abi, neglijans ak vòl","Abuse, neglect and theft"],"src":["S12"],"b":[["p","Kliyan an gen dwa pou l pa sibi abi, ni nan men anplwaye ni nan men lòt moun lakay li. Men definisyon federal yo:","The client has the right to be free from abuse, by staff or by anyone else in their home. These are the federal definitions:"],["li","Abi vèbal: pawòl, ekri oswa jès ki ensilte oswa ki imilye kliyan an.","Verbal abuse: insulting or demeaning words, writing or gestures toward the client."],["li","Abi mantal: imilyasyon, arasman, menas pinisyon oswa privasyon, entimidasyon (egzanp: viv ak laperèz lakay li).","Mental abuse: humiliation, harassment, threats of punishment or deprivation, intimidation (for example, living in fear at home)."],["li","Abi seksyèl: fòse, manipile oswa presyon pou nenpòt aktivite seksyèl kliyan an pa dakò, oswa li pa ka dakò.","Sexual abuse: forcing, manipulating or pressuring the client into any sexual activity they did not agree to, or cannot agree to."],["li","Abi fizik: nenpòt aksyon pou fè mal, tankou frape, souflete, pense.","Physical abuse: any action meant to cause harm or pain, such as hitting, slapping or pinching."],["li","Blesi orijin enkoni: yon blesi pesonn pa t wè k ap fèt, epi kliyan an pa ka eksplike.","Injury of unknown source: an injury nobody saw happen that the client cannot explain."],["li","Neglijans: pa bay bagay oswa sèvis kliyan an bezwen pou l evite domaj fizik oswa soufrans mantal.","Neglect: failing to provide goods or services the client needs to avoid physical harm or mental suffering."],["li","Vòl byen (misappropriation): pran oswa vòlè bagay lakay kliyan an.","Misappropriation of property: taking or stealing items from the client's home."]]},{"h":["Rapòte touswit","Report immediately"],"src":["S12"],"b":[["p","Nenpòt anplwaye ki remake abi, neglijans, blesi orijin enkoni oswa vòl dwe rapòte sa touswit bay ajans lan, epi bay lòt otorite dapre lwa leta a. «Touswit» vle di san reta, osito w dekouvri l.","Any staff member who notices abuse, neglect, an injury of unknown source or theft must report it immediately to the agency, and to other authorities as state law requires. “Immediately” means without delay, as soon as you discover it."],["li","Ou pa mennen ankèt. Ekri sa w wè ak sa w tande, ak lè a.","You do not investigate. Write down what you saw and heard, and when."],["li","Ajans ou ap ba w nimewo pou rapò nan leta w la. Lwa leta ka mande w rapòte tou dirèkteman.","Your agency will give you the state reporting number. State law may also require you to report directly."]]},{"h":["Dwa pou refize","The right to refuse"],"src":["S1"],"b":[["p","Kliyan an ka refize yon swen. Mande l poukisa, eksplike, pwopoze yon lòt lè, epi respekte desizyon l. Rapòte refi a bay sipèvizè w.","The client may refuse care. Ask why, explain, offer another time, and respect the decision. Report the refusal to your supervisor."]]}],"terms":[["patient rights","dwa pasyan"],["abuse","abi"],["neglect","neglijans"],["injury of unknown source","blesi orijin enkoni"],["misappropriation of property","vòl byen kliyan"],["dementia","demans"],["dignity","diyite"]],"qs":[["h801",1,["misappropriation of property","vòl byen kliyan"],["Ou wè yon kòlèg pran lajan nan bous kliyan an. Kisa sa ye, e kisa ou fè?","Se pa zafè w; se ant kòlèg la ak kliyan an","Se vòl byen kliyan (misappropriation); rapòte l touswit bay ajans lan","Mande kòlèg la remete l, epi pa di anyen si l fè l","Tann pou wè si l fè l ankò","Pran bagay lakay kliyan an se vòl byen. Ou dwe rapòte l touswit."],["You see a coworker take money from the client's purse. What is this, and what do you do?","It is not your business; it is between the coworker and the client","It is misappropriation of property; report it to the agency right away","Ask the coworker to put it back, and say nothing if they do","Wait to see if it happens again","Taking items from the client's home is misappropriation of property. You must report it immediately."]]],"check":["h801","h802","h803","h804","h805"]},{"ch":9,"cfr":"(b)(3)(ix)","observed":true,"title":["Ijyèn pèsonèl ak abiman","Personal hygiene and grooming"],"src":["S6","S12","S1"],"sections":[{"h":["Sa règ la mande","What the rule requires"],"src":["S6","S12"],"b":[["p","Règ federal la mande pou enfimyè a gade w fè swen ijyèn yo ak yon kliyan oswa yon moun k ap jwe wòl kliyan: beny nan kabann, beny an chita (sponge), nan basen oswa douch, chanpou nan lavabo, basen oswa kabann, swen zong ak po, swen bouch, ak ede kliyan an ale nan twalèt.","The federal rule requires the nurse to watch you do hygiene care with a client or a person playing the client: bed bath, sponge, tub or shower bath, shampoo in the sink, tub or bed, nail and skin care, oral hygiene, and toileting and elimination."]]},{"h":["Règ pou chak swen","Rules for every care task"],"src":["S1"],"b":[["n","Lave men w, prezante w, epi eksplike sa w pral fè.","Clean your hands, introduce yourself, and explain what you will do."],["n","Bay prive: fèmen pòt ak rido, epi kouvri pati kò ou pa p lave.","Give privacy: close doors and curtains, and keep covered the parts you are not washing."],["n","Kite kliyan an fè sa l kapab poukont li, epi kite l chwazi (rad, lè, pwodui).","Let the client do what they can, and let them choose (clothes, timing, products)."],["n","Teste dlo a anvan l touche kliyan an.","Test the water before it touches the client."],["n","Mete gan si w ka touche likid kò oswa po ki blese.","Wear gloves if you may touch body fluids or broken skin."],["n","Gade po a pandan w ap lave l, epi rapòte wouj, blesi oswa chanjman.","Look at the skin while you wash, and report redness, sores or changes."]]},{"h":["Beny nan kabann","Bed bath"],"src":["S1"],"b":[["li","Lave depi zòn ki pi pwòp yo rive nan zòn ki pi sal yo: figi, bra, pwatrin, vant, janm, do, epi zòn pèsonèl la nan fen.","Wash from cleanest to dirtiest: face, arms, chest, abdomen, legs, back, then the perineal area last."],["li","Je yo: dlo sèlman, san savon, depi kwen anndan an rive kwen deyò a, yon pati diferan nan twal la pou chak je.","Eyes: water only, no soap, from the inner corner to the outer corner, a different part of the washcloth for each eye."],["li","Chanje dlo a lè l vin frèt, gen savon oswa sal, ak anvan swen zòn pèsonèl la.","Change the water when it gets cool, soapy or dirty, and before perineal care."],["li","Seche byen, sitou ant zòtèy yo ak anba pli po yo.","Dry well, especially between the toes and under skin folds."]]},{"h":["Beny an chita, nan basen oswa douch","Sponge, tub or shower bath"],"src":["S1"],"b":[["li","Sèvi ak yon chèz douch, yon tapi ki pa glise ak ba pou kenbe si plan swen an mande yo.","Use a shower chair, non-slip mat and grab bars if the care plan calls for them."],["li","Pa janm kite kliyan an poukont li nan basen an oswa douch la si sa pa an sekirite pou li.","Never leave the client alone in the tub or shower if that is not safe for them."],["li","Rapòte toudi oswa feblès; fè l chita touswit.","Report dizziness or weakness, and have them sit down right away."]]},{"h":["Chanpou","Shampoo"],"src":["S1"],"b":[["li","Nan kabann: sèvi ak yon basen chanpou oswa yon plastik pou dlo a koule nan yon bokit, epi pwoteje dra yo.","In bed: use a shampoo tray or plastic sheet so water drains into a basin, and protect the linens."],["li","Kouvri je kliyan an ak yon ti sèvyèt, epi seche cheve a vit pou l pa frèt.","Cover the client's eyes with a small towel, and dry the hair promptly so they do not get chilled."],["li","Respekte kijan kliyan an konn okipe cheve l ak pwodui li konn sèvi.","Respect how the client usually cares for their hair and the products they use."]]},{"h":["Zong ak po","Nails and skin"],"src":["S1","S12"],"b":[["li","Tranpe men yo nan dlo tyèd, netwaye anba zong yo, epi lime yo.","Soak the hands in warm water, clean under the nails, and file them."],["li","Pa koupe zong yon kliyan ki gen dyabèt oswa move sikilasyon. Rapòte bay enfimyè a.","Do not cut the nails of a client with diabetes or poor circulation. Report to the nurse."],["li","Pa koupe zong pye si plan swen an pa mande l epi w pa fòme pou sa.","Do not cut toenails unless the care plan calls for it and you are trained."],["li","Mete krèm sou po sèk ki pa blese, men pa ant zòtèy yo.","Apply lotion to dry, unbroken skin, but not between the toes."]]},{"h":["Bouch ak dan atifisyèl","Mouth and dentures"],"src":["S1"],"b":[["li","Bwose dan ak lang, omwen de fwa pa jou, oswa jan plan swen an di.","Brush the teeth and tongue at least twice a day, or as the care plan says."],["li","Pou yon kliyan ki pa reponn: vire tèt li sou kote, sèvi ak ti kantite likid sèlman, epi pa janm mete dwèt ou nan bouch li.","For an unresponsive client: turn the head to the side, use only a small amount of liquid, and never put your fingers in their mouth."],["li","Manyen dan atifisyèl sou yon sèvyèt oswa yon basen ak dlo pou yo pa kase si yo tonbe. Rense yo ak dlo frèt oswa tyèd, pa cho.","Handle dentures over a towel or a basin of water so they do not break if dropped. Rinse with cool or lukewarm water, not hot."],["li","Sere yo nan yon bwat ki gen non kliyan an, ak dlo oswa likid tranpe.","Store them in a container labeled with the client's name, in water or soaking solution."]]},{"h":["Twalèt ak zòn pèsonèl","Toileting and perineal care"],"src":["S1"],"b":[["li","Ede kliyan an ale nan twalèt, sèvi ak yon chèz twalèt (commode), yon basen kabann (bedpan) oswa yon pistolè (urinal), selon plan swen an.","Help the client use the toilet, a commode, a bedpan or a urinal, as the care plan says."],["li","Swen zòn pèsonèl: toujou depi devan rive dèyè, ak yon pati pwòp nan twal la chak fwa.","Perineal care: always from front to back, with a clean part of the washcloth each stroke."],["li","Sak kateter: toujou pi ba pase vesi a, tib la pa pliye, epi sak la pa touche atè.","Catheter bag: always below the bladder, tubing not kinked, and the bag off the floor."],["li","Rapòte pipi oswa poupou ki pa nòmal: koulè, sant, san, oswa kliyan an pa pipi.","Report abnormal urine or stool: color, odor, blood, or the client not urinating."]]},{"h":["Abiye","Dressing"],"src":["S1","S29"],"b":[["li","Kite kliyan an chwazi rad li, epi kite l fè sa l kapab poukont li.","Let the client choose their clothes, and let them do what they can themselves."],["li","Si yon bò kò a fèb: abiye bò ki fèb la an premye. Pou dezabiye, retire rad la sou bò ki fò a an premye.","If one side is weak: dress the weak (affected) side first. To undress, take clothing off the strong side first."]]}],"terms":[["bed bath","beny nan kabann"],["perineal care","swen zòn pèsonèl"],["dentures","dan atifisyèl"],["commode","chèz twalèt"],["bedpan","basen kabann"],["urinal","pistolè"],["catheter","kateter"],["oral hygiene","ijyèn bouch"]],"skills":[{"title":["Beny nan kabann","Bed bath"],"steps":[["Lave men w, eksplike, bay prive, epi ranmase sa w bezwen.","Clean your hands, explain, give privacy, and gather supplies."],["Teste dlo a. Kouvri kliyan an ak yon dra beny, epi dekouvri sèlman pati w ap lave a.","Test the water. Cover the client with a bath blanket and uncover only the part you are washing."],["Je yo an premye: dlo sèlman, depi anndan rive deyò, yon pati diferan nan twal la pou chak je.","Eyes first: water only, inner to outer corner, a different part of the cloth for each eye."],["Figi, kou, bra, pwatrin, vant, janm, pye. Rense epi seche chak pati.","Face, neck, arms, chest, abdomen, legs, feet. Rinse and dry each part."],["Chanje dlo a. Vire kliyan an sou kote pou do a.","Change the water. Turn the client to the side for the back."],["Mete gan pou zòn pèsonèl la, depi devan rive dèyè.","Wear gloves for perineal care, front to back."],["Abiye kliyan an, ranje kabann nan, epi lave men w. Rapòte chanjman sou po a.","Dress the client, tidy the bed, and clean your hands. Report skin changes."]],"note":["Chanje dlo a chak fwa l vin frèt, gen savon oswa sal.","Change the water whenever it gets cool, soapy or dirty."]},{"title":["Ede ak douch oswa basen","Tub or shower assist"],"steps":[["Tcheke plan swen an pou ekipman: chèz douch, tapi, ba pou kenbe.","Check the care plan for equipment: shower chair, mat, grab bars."],["Teste dlo a anvan kliyan an antre.","Test the water before the client gets in."],["Ede l antre tou dousman; fè l chita sou chèz la si plan an mande l.","Help them in slowly; have them sit on the chair if the plan calls for it."],["Kite l lave sa l kapab; ede ak rès la.","Let them wash what they can; help with the rest."],["Ede l soti, seche l byen, epi mete l chita pou l abiye.","Help them out, dry well, and seat them to dress."]],"note":["Pa janm kite yon kliyan ki pa an sekirite poukont li nan basen oswa douch la.","Never leave a client who is not safe alone in the tub or shower."]},{"title":["Chanpou nan kabann","Shampoo in bed"],"steps":[["Mete yon plastik oswa yon basen chanpou anba tèt kliyan an, ak yon bokit pou dlo a.","Place a plastic sheet or shampoo tray under the head, with a basin for the water."],["Kouvri je l ak yon ti sèvyèt.","Cover the eyes with a small towel."],["Mouye cheve a ak dlo tyèd ou fin teste, mete chanpou, masaj po tèt la.","Wet the hair with tested warm water, apply shampoo, massage the scalp."],["Rense nèt, epi seche cheve a vit.","Rinse well, and dry the hair promptly."],["Penyen l jan kliyan an renmen, epi chanje dra ki mouye.","Comb it the way the client likes, and change any wet linens."]],"note":["Respekte pwodui ak abitid kliyan an pou cheve l.","Respect the client's hair products and habits."]},{"title":["Swen zong men","Fingernail care"],"steps":[["Tcheke plan swen an. Si kliyan an gen dyabèt oswa move sikilasyon, pa koupe zong yo.","Check the care plan. If the client has diabetes or poor circulation, do not cut the nails."],["Tranpe men yo nan dlo tyèd kèk minit.","Soak the hands in warm water for a few minutes."],["Netwaye anba zong yo ak yon bwa oswa zouti apwopriye.","Clean under the nails with an orange stick or proper tool."],["Lime zong yo pou yo lis.","File the nails smooth."],["Mete krèm sou men yo, epi rapòte nenpòt blesi.","Apply lotion to the hands, and report any sores."]],"note":["Zong pye: sèlman si plan swen an mande l epi w fòme pou sa.","Toenails: only if the care plan calls for it and you are trained."]},{"title":["Swen bouch ak dan atifisyèl","Mouth and denture care"],"steps":[["Lave men w, mete gan, epi fè kliyan an chita dwat.","Clean your hands, put on gloves, and sit the client upright."],["Bwose dan ak lang tou dousman, epi kite l rense.","Brush the teeth and tongue gently, and let them rinse."],["Dan atifisyèl: retire yo, epi bwose yo sou yon sèvyèt oswa yon basen dlo.","Dentures: remove them, and brush them over a towel or a basin of water."],["Rense yo ak dlo frèt oswa tyèd, pa cho.","Rinse with cool or lukewarm water, not hot."],["Remete yo oswa sere yo nan yon bwat ki gen non kliyan an, ak dlo.","Put them back or store them in a labeled container with water."]],"note":["Rapòte senyen, blesi nan bouch oswa dan ki pa byen chita.","Report bleeding, mouth sores or loose-fitting dentures."]},{"title":["Basen kabann ak twalèt","Bedpan and toileting"],"steps":[["Bay prive epi mete gan.","Give privacy and put on gloves."],["Fè kliyan an vire sou kote, mete basen an anba l, epi vire l tounen sou do.","Turn the client to the side, place the bedpan, and roll them back onto it."],["Leve tèt kabann nan si sa pèmèt, epi kite papye twalèt ak sonèt nan rive men l.","Raise the head of the bed if allowed, and leave toilet paper and a call bell within reach."],["Retire basen an, netwaye depi devan rive dèyè, epi ede l lave men l.","Remove the bedpan, clean front to back, and help them clean their hands."],["Gade sa ki ladan l, vide l, netwaye basen an, epi rapòte sa ki pa nòmal.","Observe the contents, empty and clean the bedpan, and report anything abnormal."]],"note":["Ekri pipi oswa poupou si plan swen an mande w mezire yo.","Record output if the care plan asks you to measure it."]},{"title":["Swen zòn pèsonèl","Perineal care"],"steps":[["Bay prive, eksplike, epi mete gan.","Give privacy, explain, and put on gloves."],["Teste dlo a epi kouvri kliyan an, dekouvri sèlman zòn nan.","Test the water and keep the client covered except the area."],["Lave depi devan rive dèyè, ak yon pati pwòp nan twal la chak fwa.","Wash front to back, with a clean part of the cloth each stroke."],["Rense epi seche byen.","Rinse and dry well."],["Retire gan yo, lave men w, epi rapòte wouj, likid oswa sant ki pa nòmal.","Remove gloves, clean your hands, and report redness, discharge or unusual odor."]],"note":["Depi devan rive dèyè anpeche mikwòb poupou antre nan pipi.","Front to back keeps stool germs away from the urinary tract."]}],"qs":[["h901",0,["bed bath","beny nan kabann"],["Pandan yon beny nan kabann, kijan pou w lave je kliyan an?","Ak dlo sèlman, depi kwen anndan rive kwen deyò","Ak savon, depi deyò rive anndan","Ak alkòl","Ak menm pati nan twal la pou de je yo","Pa mete savon nan je. Lave depi anndan rive deyò, ak yon pati diferan nan twal la pou chak je, pou w pa pote mikwòb."],["During a bed bath, how should you wash the client's eyes?","With water only, from the inner corner to the outer corner","With soap, from outer to inner","With alcohol","With the same part of the cloth for both eyes","No soap in the eyes. Wash inner to outer, with a different part of the cloth for each eye, so you do not spread germs."]]],"check":["h901","h902","h903","h904","h905"]},{"ch":10,"cfr":"(b)(3)(x)","observed":true,"title":["Transfè ak mache an sekirite","Safe transfer and ambulation"],"src":["S6","S12","S1"],"sections":[{"h":["Sa règ la mande","What the rule requires"],"src":["S6","S12"],"b":[["p","Enfimyè a dwe gade w transfere yon kliyan (egzanp: kabann rive nan chèz) epi ede l mache an sekirite, ak oswa san aparèy (bekiy, mache, chèz woulant).","The nurse must watch you transfer a client (for example, bed to chair) and help them walk safely, with or without devices (cane, walker, wheelchair)."]]},{"h":["Bon mekanik kò","Good body mechanics"],"src":["S1"],"b":[["li","Pye w louvri nan lajè zepòl ou pou w gen bon baz.","Feet shoulder-width apart for a wide base."],["li","Pliye jenou w, pa do w. Kenbe do w dwat.","Bend your knees, not your back. Keep your back straight."],["li","Kenbe kliyan an oswa bagay la toupre kò w.","Keep the client or object close to your body."],["li","Vire tout kò w ak pye w; pa tòde do w.","Turn your whole body with your feet; do not twist your back."],["li","Mande èd si kliyan an twò lou oswa plan swen an mande de moun.","Ask for help if the client is too heavy or the care plan calls for two people."]]},{"h":["Senti mache ak chèz woulant","Gait belt and wheelchair"],"src":["S1"],"b":[["li","Mete senti mache a sou rad la, nan ren, epi sere l pou w ka glise de dwèt anba l.","Put the gait belt on over clothing at the waist, snug enough to slide two fingers under it."],["li","Pa mete l sou yon blesi, yon tib oswa yon vant ki fèk opere si plan swen an pa pèmèt sa.","Do not put it over a wound, a tube or a recent abdominal surgery unless the care plan allows it."],["li","Bloke fren chèz woulant lan anvan chak transfè, epi leve repoze pye yo.","Lock the wheelchair brakes before every transfer, and lift the footrests out of the way."],["li","Mete chèz la sou bò ki fò a, an ang ak kabann nan.","Place the chair on the client's strong side, angled to the bed."]]},{"h":["Mache ak yon aparèy","Walking with a device"],"src":["S1"],"b":[["li","Bekiy (cane): kliyan an kenbe l nan men bò ki fò a. Bekiy la avanse ansanm ak janm ki fèb la.","Cane: the client holds it in the hand on the strong side. The cane moves forward with the weak leg."],["li","Mache (walker): avanse mache a, apre sa janm ki fèb la, apre sa janm ki fò a. Pa leve l twò lwen devan.","Walker: move the walker forward, then the weak leg, then the strong leg. Do not push it too far ahead."],["li","Kanpe bò ki fèb la, yon ti jan dèyè kliyan an, epi kenbe senti mache a.","Stand on the weak side, slightly behind the client, holding the gait belt."],["li","Soulye ki pa glise, chemen ki pwòp, epi pa prese.","Non-skid shoes, a clear path, and no rushing."]]},{"h":["Toudi ak tonbe","Dizziness and falls"],"src":["S1"],"b":[["li","Fè kliyan an chita sou kwen kabann nan kèk minit anvan l kanpe: tansyon ka desann lè l leve vit.","Have the client sit on the edge of the bed for a few minutes before standing: blood pressure can drop when rising quickly."],["li","Si l di l toudi, fè l chita ankò epi rapòte l.","If they say they are dizzy, have them sit back down and report it."],["li","Si l kòmanse tonbe pandan l ap mache: pa eseye kenbe l kanpe. Rale l sou ou ak senti mache a, epi desann li dousman atè, pwoteje tèt li.","If they start to fall while walking: do not try to hold them up. Pull them toward you with the gait belt and ease them gently to the floor, protecting the head."],["li","Apre yon tonbe, pa leve l poukont ou. Rele enfimyè a oswa ajans ou, epi rapòte.","After a fall, do not lift them alone. Call the nurse or agency, and report it."]]}],"terms":[["body mechanics","mekanik kò"],["gait belt","senti mache"],["transfer","transfè"],["ambulation","mache"],["walker","mache (walker)"],["cane","bekiy"],["wheelchair","chèz woulant"],["strong side / weak side","bò ki fò / bò ki fèb"]],"skills":[{"title":["Transfè kabann rive nan chèz","Bed-to-chair transfer"],"steps":[["Swiv plan swen an. Eksplike kliyan an sa n pral fè.","Follow the care plan. Explain the move to the client."],["Mete chèz la sou bò ki fò a, an ang, epi bloke wou yo.","Place the chair on the strong side at an angle and lock the wheels."],["Fè kliyan an chita sou kwen kabann nan, pye l atè, epi tann kèk minit.","Have the client sit on the edge of the bed, feet flat on the floor, and wait a few minutes."],["Mete soulye ki pa glise pou kliyan an, ak yon senti mache (gait belt).","Put non-skid shoes on the client and apply a gait belt."],["Konte 1-2-3 ansanm, kliyan an kanpe, epi nou vire tou dousman.","Count 1-2-3 together, the client stands, and you pivot slowly."],["Desann kliyan an dousman nan chèz la.","Lower the client gently into the chair."]],"note":["Pliye jenou w, kenbe do w dwat. Pa janm leve kliyan an pa bra l.","Bend your knees and keep your back straight. Never lift a client by the arms."]},{"title":["Mache ak yon walker ak senti mache","Walking with a walker and gait belt"],"steps":[["Tcheke plan swen an, mete soulye ki pa glise, epi mete senti mache a.","Check the care plan, put on non-skid shoes, and apply the gait belt."],["Fè kliyan an chita sou kwen kabann nan, epi mande l si l toudi.","Have the client sit on the edge of the bed, and ask if they feel dizzy."],["Ede l kanpe; li kenbe de manch walker a.","Help them stand; they hold both walker handles."],["Kanpe bò ki fèb la, yon ti jan dèyè, men w sou senti a.","Stand on the weak side, slightly behind, hand on the belt."],["Walker a avanse, apre sa janm ki fèb la, apre sa janm ki fò a.","Walker forward, then the weak leg, then the strong leg."],["Fini chita nan yon chèz, epi ekri distans lan ak kijan l te mache.","Finish seated in a chair, and record the distance and how they walked."]],"note":["Si l kòmanse tonbe, desann li dousman atè ak senti a; pa eseye kenbe l kanpe.","If they start to fall, ease them to the floor with the belt; do not try to hold them up."]},{"title":["Sekirite chèz woulant","Wheelchair safety"],"steps":[["Bloke fren yo anvan kliyan an antre oswa soti.","Lock the brakes before the client gets in or out."],["Leve oswa retire repoze pye yo pandan transfè a.","Raise or swing away the footrests during the transfer."],["Lè l chita, mete pye l sou repoze pye yo.","Once seated, place the feet on the footrests."],["Pouse chèz la pa devan; desann yon ranp oswa antre nan yon asansè pa dèyè.","Push forward; go down a ramp or into an elevator backward."],["Tcheke pozisyon an epi bloke fren yo chak fwa w kanpe.","Check positioning and lock the brakes every time you stop."]],"note":["Kenbe men kliyan an sou kuis li pou yo pa pran nan wou yo.","Keep the client's hands in the lap so they do not catch in the wheels."]}],"qs":[["h1001",0,["wheelchair brakes","fren chèz woulant"],["Kisa pou w fè anvan w transfere yon kliyan nan yon chèz woulant?","Bloke fren yo epi leve repoze pye yo","Kite chèz la lib pou l fasil pou deplase","Mete chèz la sou bò ki fèb la","Mande kliyan an sote nan chèz la","Bloke fren yo pou chèz la pa glise, epi leve repoze pye yo pou kliyan an pa frape yo."],["What do you do before transferring a client into a wheelchair?","Lock the brakes and raise the footrests","Leave it unlocked so it moves easily","Put the chair on the weak side","Ask the client to jump into the chair","Lock the brakes so the chair does not roll, and move the footrests so the client does not trip on them."]]],"check":["h1001","h1002","h1003","h1004","h1005"]},{"ch":11,"cfr":"(b)(3)(xi)","observed":true,"title":["Ranje mouvman ak pozisyon","Range of motion and positioning"],"src":["S6","S12","S1"],"sections":[{"h":["Sa règ la mande","What the rule requires"],"src":["S6","S12"],"b":[["p","Enfimyè a dwe gade w fè egzèsis ranje mouvman (range of motion, ROM) ak chanje pozisyon kliyan an. Swiv sèlman egzèsis ki nan plan swen an, jan terapis la oswa enfimyè a ekri yo.","The nurse must watch you do range-of-motion (ROM) exercises and reposition a client. Do only the exercises in the care plan, as the therapist or nurse wrote them."]]},{"h":["Pasif oswa aktif","Passive or active"],"src":["S1"],"b":[["li","Aktif: kliyan an fè mouvman an poukont li.","Active: the client moves the joint on their own."],["li","Aktif ak èd: kliyan an fè yon pati, ou ede l fini.","Active-assisted: the client does part of it and you help finish."],["li","Pasif: ou fè mouvman an pou kliyan an ki pa ka fè l.","Passive: you move the joint for a client who cannot."]]},{"h":["Règ pou ROM","Rules for ROM"],"src":["S1"],"b":[["li","Sipòte jwenti a: yon men anwo, yon men anba li.","Support the joint: one hand above it, one hand below it."],["li","Fè mouvman yo dousman, regilye, epi menm kantite fwa jan plan an di.","Move slowly and smoothly, the number of times the plan says."],["li","Pa janm fòse yon jwenti pi lwen pase kote l rive fasil.","Never force a joint past where it moves easily."],["li","Rete si kliyan an gen doulè, epi rapòte l.","Stop if the client has pain, and report it."],["li","Pa fè ROM sou kou oswa sou yon jwenti ki fèk opere, si plan swen an pa mande l.","Do not do ROM on the neck or a recently operated joint unless the care plan calls for it."]]},{"h":["Pozisyon ak chanje pozisyon","Positioning and repositioning"],"src":["S1"],"b":[["li","Yon kliyan ki pa ka deplase poukont li bezwen chanje pozisyon omwen chak 2 èdtan, oswa jan plan swen an di.","A client who cannot move on their own needs repositioning at least every 2 hours, or as the care plan says."],["li","Sou kote: yon zòrye ant jenou yo ak dèyè do a.","Side-lying: a pillow between the knees and one behind the back."],["li","Leve talon yo (float heels) ak yon zòrye anba mollèt yo pou talon yo pa peze kabann nan.","Float the heels with a pillow under the calves so the heels do not press on the bed."],["li","Fowler: tèt kabann nan leve (anviwon 45 a 60 degre), bon pou manje ak respire.","Fowler's: head of the bed raised (about 45 to 60 degrees), good for eating and breathing."],["li","Pa rale kliyan an sou dra yo: sa ka chire po a. Sèvi ak yon dra pou leve (draw sheet) ak yon lòt moun.","Do not drag the client across the sheets: it can tear the skin. Use a draw sheet and a second person."]]}],"terms":[["range of motion (ROM)","ranje mouvman"],["passive","pasif"],["active","aktif"],["joint","jwenti"],["reposition","chanje pozisyon"],["Fowler's position","pozisyon Fowler"],["float the heels","leve talon yo"],["draw sheet","dra pou leve"]],"skills":[{"title":["ROM pasif: zepòl","Passive ROM: shoulder"],"steps":[["Lave men w, eksplike, epi kouche kliyan an sou do.","Clean your hands, explain, and lay the client on their back."],["Sipòte koud la ak ponyèt la.","Support the elbow and the wrist."],["Leve bra a dousman devan, rive anlè tèt la, epi desann li (flexion/extension).","Raise the arm slowly forward, up over the head, and back down (flexion/extension)."],["Deplase bra a sou kote, lwen kò a, epi tounen (abduction/adduction).","Move the arm out to the side, away from the body, and back (abduction/adduction)."],["Fè chak mouvman kantite fwa plan swen an di; rete si gen doulè.","Repeat each move as many times as the care plan says; stop if there is pain."],["Ekri sa w fè ak kijan kliyan an reyaji.","Record what you did and how the client responded."]],"note":["Pa janm fòse jwenti a.","Never force the joint."]},{"title":["ROM pasif: ranch ak jenou","Passive ROM: hip and knee"],"steps":[["Kliyan an sou do. Sipòte anba jenou an ak talon an.","Client on their back. Support under the knee and the heel."],["Pliye jenou an epi pote l vè pwatrin nan dousman, epi lonje l ankò.","Bend the knee and bring it gently toward the chest, then straighten it."],["Ak janm nan dwat, deplase l sou kote, lwen lòt janm nan, epi tounen.","With the leg straight, move it out to the side, away from the other leg, and back."],["Fè kantite fwa plan an di; rete si gen doulè.","Repeat as the plan says; stop if there is pain."],["Kouvri kliyan an epi ekri sa w fè.","Cover the client and record what you did."]],"note":["Rapòte doulè, rèd oswa anflamasyon ki fèk parèt.","Report new pain, stiffness or swelling."]},{"title":["Vire kliyan an sou kote","Turning the client onto the side"],"steps":[["Eksplike, bay prive, epi bloke wou kabann nan si l genyen.","Explain, give privacy, and lock the bed wheels if it has them."],["Kanpe sou bò kote kliyan an pral vire a. Kwaze bra l sou pwatrin li epi kwaze janm ki lwen an sou lòt la.","Stand on the side the client will turn toward. Cross their arms over the chest and the far leg over the near one."],["Mete men w sou zepòl ak ranch ki lwen an, epi vire l dousman vè ou.","Place your hands on the far shoulder and hip, and roll them gently toward you."],["Mete yon zòrye dèyè do a ak yon lòt ant jenou yo.","Place a pillow behind the back and another between the knees."],["Tcheke ke zòrèy, zepòl ak talon yo pa peze, epi kite sonèt la nan rive men l.","Check that the ears, shoulder and heels are not under pressure, and leave the call bell within reach."]],"note":["Ekri lè w chanje pozisyon an; swiv orè plan swen an.","Record the time you repositioned; follow the care plan's schedule."]}],"qs":[["h1101",0,["passive ROM","ROM pasif"],["Kisa ROM pasif ye?","Ou fè mouvman jwenti a pou kliyan an ki pa ka fè l","Kliyan an fè egzèsis la poukont li","Kliyan an mache nan kay la","Yon egzèsis ak pwa lou","Nan ROM pasif, ou deplase jwenti a pou kliyan an. Nan ROM aktif, kliyan an fè l poukont li."],["What is passive range of motion?","You move the joint for a client who cannot","The client exercises on their own","The client walks around the house","An exercise with heavy weights","In passive ROM, you move the joint for the client. In active ROM, the client does it on their own."]]],"check":["h1101","h1102","h1103","h1104","h1105"]},{"ch":12,"cfr":"(b)(3)(xii)","title":["Manje ak likid","Nutrition and fluid intake"],"src":["S6","S1","S15"],"sections":[{"h":["Yon bon alimantasyon","Good nutrition"],"src":["S1"],"b":[["p","Yon kò ki byen nouri pi fò, li geri pi byen, epi li reziste enfeksyon. Swiv rejim espesyal ki nan plan swen an chak fwa.","A well-nourished body is stronger, heals better and fights infection. Follow any special diet in the care plan every time."],["li","Mwens sèl (low sodium): pou tansyon wo oswa pwoblèm kè. Chwazi manje fre (vyann fre, legim); evite soup an bwat, vyann trete, nouy enstantane ak chips.","Low sodium: for high blood pressure or heart problems. Choose fresh foods (fresh meat, vegetables); avoid canned soups, processed meats, instant noodles and chips."],["li","Rejim pou dyabèt: kontwole sik ak kantite karbonidrat.","Diabetic diet: controls sugar and carbohydrates."],["li","Manje mou oswa moulen (mechanical soft, puree): pou moun ki gen pwoblèm pou kraze oswa vale.","Soft or pureed food (mechanical soft, puree): for people with chewing or swallowing problems."],["li","Likid epè (thickened liquids): pou moun ki gen pwoblèm pou vale. Swiv konsistans lan egzakteman: likid ki pa epè ase ka antre nan poumon.","Thickened liquids: for people with swallowing problems. Follow the thickness exactly: liquid that is too thin can go into the lungs."]]},{"h":["Likid ak dezidratasyon","Fluids and dehydration"],"src":["S1"],"b":[["li","Ankouraje likid pandan jounen an, sòf si plan swen an limite yo.","Encourage fluids throughout the day, unless the care plan limits them."],["li","Si gen restriksyon likid, swiv li egzakteman epi mezire sa kliyan an bwè si yo mande w.","If fluids are restricted, follow it exactly and measure intake if asked."],["li","Si yon kliyan ki gen restriksyon likid swaf, ofri l swen bouch oswa krèm pou po bouch. Bay ti mòso glas sèlman si plan swen an pèmèt sa: yo konte kòm likid. Rapòte swaf la bay enfimyè a.","If a client on a fluid restriction is thirsty, offer mouth care or lip moisturizer. Give ice chips only if the care plan allows: they count as fluid. Report the thirst to the nurse."],["li","Siy dezidratasyon: bouch sèk, pipi fonse oswa pi piti pipi, tèt vire, konfizyon. Rapòte yo.","Signs of dehydration: dry mouth, dark urine or less urine, dizziness, confusion. Report them."]]},{"h":["Ede kliyan an manje","Helping the client eat"],"src":["S1"],"b":[["li","Fè kliyan an chita dwat, toupre 90 degre si l kapab, pou l manje, epi rete chita kèk tan apre.","Sit the client upright, as close to 90 degrees as they can, to eat, and keep them upright for a while after."],["li","Ti mòso, epi kite l kraze ak vale anvan pwochen mòso a. Pa prese l.","Small bites, and let them chew and swallow before the next bite. Do not rush."],["li","Gade si manje rete nan bouch li (anndan machwè). Fè l sonje kraze ak vale, epi rapòte l.","Check for food held in the cheeks (pocketing). Remind them to chew and swallow, and report it."],["li","Ankouraje l manje poukont li otan l kapab.","Encourage them to feed themselves as much as they can."],["li","Ekri konbyen l manje (egzanp: 50%) ak konbyen l bwè si yo mande w.","Record how much they ate (for example, 50%) and drank if asked."],["li","Rapòte touse oswa toufe pandan manje.","Report coughing or choking during meals."]]},{"h":["Sekirite manje","Food safety"],"src":["S15","S19"],"b":[["li","Frijidè a dwe nan 40°F (4°C) oswa pi ba. Frizè a nan 0°F (-18°C) oswa pi ba.","Keep the refrigerator at 40°F (4°C) or below and the freezer at 0°F (-18°C) or below."],["li","Rès vyann oswa poul kwit: 3 a 4 jou nan frijidè.","Leftover cooked meat or poultry: 3 to 4 days in the refrigerator."],["li","Mete manje ki rete nan frijidè anvan 2 èdtan apre w fin kwit li (anvan 1 èdtan si fè plis pase 90°F). Jete manje ki rete deyò pi lontan pase sa.","Refrigerate leftovers within 2 hours of cooking (within 1 hour if it is above 90°F). Throw out food left out longer."],["li","Lave men w anvan w prepare manje, epi jete manje ki gate.","Clean your hands before preparing food, and throw out spoiled food."]]},{"h":["Chwa kliyan an","The client's choices"],"src":["S1"],"b":[["p","Kliyan an ka refize manje. Pwopoze yon lòt chwa ki nan rejim li, respekte desizyon l, note konbyen l manje, epi rapòte si sa kontinye.","The client may refuse food. Offer another choice within their diet, respect the decision, note how much they ate, and report if it continues."]]}],"terms":[["special diet","rejim espesyal"],["low sodium","mwens sèl"],["thickened liquids","likid epè"],["fluid restriction","restriksyon likid"],["dehydration","dezidratasyon"],["intake","sa kliyan an manje ak bwè"],["pocketing food","kenbe manje nan machwè"]],"qs":[["h1201",2,["thickened liquids","likid epè"],["Plan swen an di kliyan an bezwen likid epè. Li mande yon vè dlo nòmal. Kisa ou fè?","Ba l dlo nòmal, paske kliyan an gen dwa mande l","Ba l mwatye vè dlo nòmal, dousman, ak yon chalimo","Ba l likid la nan konsistans plan swen an mande, epi eksplike poukisa","Pa ba l anyen pou bwè","Likid ki pa epè ase ka antre nan poumon moun ki gen pwoblèm pou vale. Swiv konsistans lan egzakteman."],["The care plan says the client needs thickened liquids. They ask for a glass of plain water. What do you do?","Give plain water, because the client has the right to ask for it","Give half a glass of plain water, slowly, through a straw","Give the liquid at the thickness the care plan requires, and explain why","Give nothing to drink","Thin liquid can go into the lungs of someone with swallowing problems. Follow the thickness exactly."]]],"check":["h1201","h1202","h1203","h1204","h1205"]},{"ch":13,"cfr":"(b)(3)(xiii)","title":["Rekonèt ak rapòte chanjman nan po","Recognizing and reporting skin changes"],"src":["S6","S12","S1"],"sections":[{"h":["Poukisa po a enpòtan","Why skin matters"],"src":["S1","S12"],"b":[["p","Avèk laj, po a vin pi mens, pi sèk, epi li chire fasil. Lè yon moun rete nan menm pozisyon twò lontan, presyon an ka fè blesi presyon (eska) sou zo yo. Sijè sa a te ajoute nan fòmasyon federal la an 2018.","With age, skin gets thinner, drier and tears easily. When a person stays in one position too long, pressure can cause pressure injuries (bedsores) over the bones. This subject was added to federal aide training in 2018."]]},{"h":["Ki kote pou w gade","Where to look"],"src":["S1"],"b":[["li","Sou zo yo: talon, ranch, zo koksis (tailbone), koud, zo zepòl, dèyè tèt.","Over bones: heels, hips, tailbone, elbows, shoulder blades, back of the head."],["li","Anba tete, nan pli po, ant zòtèy.","Under the breasts, in skin folds, between the toes."],["li","Anwo zòrèy kote tib oksijèn nan kouche.","The tops of the ears where oxygen tubing rests."]]},{"h":["Sa pou w rapòte","What to report"],"src":["S1"],"b":[["li","Yon kote ki wouj epi ki rete wouj apre w retire presyon an.","A red area that stays red after you relieve the pressure."],["li","Yon kote ki cho, di oswa mou, ki diferan de po ki bò kote l.","An area that feels warm, hard or soft compared with the skin around it."],["li","Ti bous dlo (anpoul), po ki louvri, chire, gratèl, nouvo mak blese, chanjman koulè.","Blisters, open skin, skin tears, rashes, new bruises, color changes."],["li","Blesi oswa fant sou pye, sitou pou moun ki gen dyabèt.","Sores or cracks on the feet, especially for people with diabetes."]]},{"h":["Prevansyon","Prevention"],"src":["S1"],"b":[["li","Chanje pozisyon kliyan an omwen chak 2 èdtan si l nan kabann, oswa jan plan swen an di.","Change the client's position at least every 2 hours in bed, or as the care plan says."],["li","Kenbe po a pwòp ak sèk, sitou touswit apre pipi oswa poupou sou li.","Keep skin clean and dry, especially right after incontinence."],["li","Mete krèm sou po ki sèk, men pa ant zòtèy yo.","Moisturize dry skin, but not between the toes."],["li","Leve kliyan an ak yon dra pou deplase l nan kabann. Pa trennen l: friksyon an blese po a.","Use a lift sheet to move the client in bed. Do not drag them: friction injures the skin."],["li","Kenbe dra yo lis, san pli ni miyèt.","Keep sheets smooth, without wrinkles or crumbs."],["li","Pa masaj yon kote ki wouj sou yon zo.","Do not massage a red area over a bone."],["li","Ankouraje manje ak likid jan plan swen an di: yon kò ki byen nouri geri pi byen.","Encourage food and fluids as the care plan says: a well-nourished body heals better."]]}],"terms":[["pressure injury","blesi presyon (eska)"],["skin tear","po ki chire"],["bony area","kote ki gen zo"],["friction","friksyon"],["lift sheet","dra pou leve"],["blister","anpoul (ti bous dlo)"]],"skills":[{"title":["Tcheke po a chak jou","Daily skin check"],"steps":[["Lave men w, eksplike, epi pwoteje vi prive kliyan an.","Clean your hands, explain, and protect the client's privacy."],["Pandan swen (beny, abiye), gade po a de tèt rive nan pye.","During care (bathing, dressing), look at the skin from head to toe."],["Konsantre sou talon, ranch, zo koksis, koud, zo zepòl, dèyè tèt ak zòrèy.","Focus on heels, hips, tailbone, elbows, shoulder blades, back of the head and ears."],["Retire presyon an sou yon kote ki wouj, epi gade ankò apre kèk minit.","Relieve pressure on a red area, and check again after a few minutes."],["Ekri sa w wè (ki kote, gwosè, koulè) epi rapòte bay enfimyè a.","Record what you see (where, size, color) and report it to the nurse."]],"note":["Pa masaj yon kote ki wouj sou yon zo.","Do not massage a red area over a bone."]}],"qs":[["h1301",1,["pressure injury","blesi presyon"],["Ki kote blesi presyon fòme pi souvan?","Sou kote ki mou, tankou vant lan","Sou zo, tankou talon ak zo koksis","Nan pla men ak do men","Sou fwon","Blesi presyon fòme sou zo kote presyon an pi fò, tankou talon, ranch ak zo koksis."],["Where do pressure injuries most often form?","On soft areas, such as the belly","Over bones, such as the heels and tailbone","On the palms and the backs of the hands","On the forehead","Pressure injuries form over bones where pressure is greatest, such as the heels, hips and tailbone."]]],"check":["h1301","h1302","h1303","h1304","h1305"]},{"ch":14,"cfr":"(b)(3)(xiv)","title":["Lòt travay, medikaman ak règ pou rete kalifye","Other tasks, medications and staying qualified"],"src":["S6","S12"],"sections":[{"h":["Travay anplis","Extra tasks"],"src":["S6","S12"],"b":[["p","Ajans lan ka mande w fè lòt travay sèlman si lwa leta pèmèt yo. Pou nenpòt konpetans ki pa nan lis debaz la, ajans lan dwe ba w fòmasyon anvan.","The agency may ask you to do other tasks only if state law allows them. For any skill not on the basic list, the agency must train you first."],["li","Si yon règ leta pi sevè pase règ federal la, se règ ki pi sevè a ki aplike. Mande ajans ou sa leta w mande.","If a state rule is stricter than the federal rule, the stricter rule applies. Ask your agency what your state requires."]]},{"h":["Medikaman: sa w ka fè ak sa w pa ka fè","Medications: what you can and cannot do"],"src":["S12"],"b":[["p","«Pran medikaman pou kont li» vle di kliyan an (oswa moun k ap okipe l) jere tout bagay: kenbe medikaman yo an sekirite, pran bon dòz la, pran l a lè, epi rele famasi a.","“Self-administration” means the client (or their caregiver) manages everything: storing medications safely, taking the right dose, taking it on time, and calling the pharmacy."],["li","Ou ka: pote medikaman an jan kliyan an mande, ba l dlo, fè l sonje, mete yon krèm san preskripsyon sou po ki pa blese jan yo montre w.","You may: bring the medication as the client asks, give fluids, give reminders, and apply a non-prescription cream to unbroken skin as instructed."],["li","Ou pa ka: chwazi oswa chanje dòz, ranpli bwat grenn semèn nan, bay piki, oswa deside si kliyan an bezwen yon medikaman.","You may not: choose or change a dose, fill the weekly pill organizer, give injections, or decide whether the client needs a medication."],["li","Rapòte si kliyan an rate dòz, refize medikaman, oswa gen yon reyaksyon.","Report if the client misses doses, refuses a medication, or has a reaction."]]},{"h":["Evalyasyon konpetans","The competency evaluation"],"src":["S6","S12"],"b":[["li","Yon enfimyè (RN) fè evalyasyon an. Li dwe gade w fè konpetans pratik yo ak yon kliyan oswa yon moun k ap jwe wòl kliyan.","A registered nurse runs the evaluation. They must watch you perform the hands-on skills with a client or a person playing the client."],["li","Si yo bay ou «pa satisfezan» nan yon travay, ou pa ka fè l san siveyans dirèk yon RN jiskaske w resevwa fòmasyon ankò epi w reyisi yon nouvo evalyasyon.","If you are rated “unsatisfactory” on a task, you cannot do it without direct RN supervision until you are retrained and pass a new evaluation."],["li","Si w gen «pa satisfezan» nan plis pase yon sèl domèn obligatwa, ou pa pase evalyasyon an.","If you are rated unsatisfactory in more than one required area, you do not pass the evaluation."]]},{"h":["Siveyans","Supervision"],"src":["S12"],"b":[["li","Si kliyan an resevwa swen enfimyè oswa terapi: yon RN oswa terapis evalye swen ou omwen chak 14 jou. Ou pa oblije la.","If the client gets nursing or therapy: an RN or therapist reviews your care at least every 14 days. You do not have to be present."],["li","Si kliyan an pa resevwa swen sa yo: RN lan fè yon vizit an pèsòn chak 60 jou.","If the client does not get those services: the RN makes an in-person visit every 60 days."],["li","Yon pwofesyonèl ap obsève w pandan w ap bay swen omwen yon fwa pa ane (oswa de fwa pa ane pou swen ki pa teknik).","A professional will watch you give care at least once a year (twice a year for non-skilled care)."],["li","Si yo jwenn yon pwoblèm nan swen ou, ou dwe fè fòmasyon ankò ak yon nouvo evalyasyon pou konpetans sa a ak konpetans ki gen rapò.","If a problem is found in your care, you must be retrained and re-evaluated on that skill and related skills."]]},{"h":["Rete kalifye","Staying qualified"],"src":["S6","S12"],"b":[["li","Omwen 12 èdtan fòmasyon kontinyèl (in-service) chak 12 mwa. Si fòmasyon an fèt pandan w ap bay swen, kliyan an dwe konnen epi dakò.","At least 12 hours of in-service training every 12 months. If training happens during care, the client must be told and agree."],["li","Si w pase 24 mwa youn dèyè lòt san w pa travay kòm ed pou lajan, ou dwe refè yon pwogram fòmasyon oswa evalyasyon.","If you go 24 months in a row without paid aide work, you must complete a training or competency program again."],["li","Yon CNA ki an règ sou rejis eta a satisfè kondisyon fòmasyon an pou travay kòm ed swen a domisil.","A CNA in good standing on the state registry meets the training requirement to work as a home health aide."]]}],"terms":[["competency evaluation","evalyasyon konpetans"],["unsatisfactory","pa satisfezan"],["in-service training","fòmasyon kontinyèl"],["supervisory visit","vizit siveyans"],["nurse aide registry","rejis ed enfimyè"],["pill organizer","bwat grenn"]],"qs":[["h1401",1,["unsatisfactory","pa satisfezan"],["Ou resevwa «pa satisfezan» nan beny nan kabann pandan evalyasyon an. Kisa sa vle di?","Ou pa ka janm bay benyen nan kabann ankò, menm apre fòmasyon","Ou ka fè l sèlman anba siveyans dirèk yon RN jiskaske w refè fòmasyon epi w pase","Ou ka fè l nòmalman","Ou ka fè l si yon moun nan fanmi kliyan an sipèvize w","Yon travay ou pa satisfezan ladan l mande siveyans dirèk RN jiskaske w refè fòmasyon epi w pase yon nouvo evalyasyon."],["You are rated “unsatisfactory” on the bed bath during your evaluation. What does that mean?","You can never give a bed bath again, even after retraining","You may do it only under direct RN supervision until you are retrained and pass","You may do it as usual","You may do it if a family member of the client supervises you","A task rated unsatisfactory requires direct RN supervision until you are retrained and pass a new evaluation."]]],"check":["h1401","h1402","h1403","h1404","h1405"]}];
